window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["rna"]={"id": "rna", "title": "RNA的生物合成和转录后加工", "sub": "93页教材逐页详解 · 50张概念图 · 38道考题", "sub2": "转录机制 · 真核转录与抑制剂 · 转录后加工 · RNA复制/RNAi/逆转录", "modules": [{"i": 0, "name": "模块一：转录机制(启动子/酶/过程)", "slides": [{"i": 0, "sec": "RNA的生物合成和转录后加工", "title": "第十一章 RNA的生物合成 (p1)", "notes": "第十一章 RNA的生物合成。\u000b第一节 DNA指导下RNA的合成(转录)；\u000b第二节 RNA的转录后加工；\u000b第三节 RNA的复制；\u000b第四节 逆转录作用(RNA指导的DNA合成)。\u000b核心：转录机制→转录后加工→RNA复制→逆转录。", "page": 1, "level": "掌握", "img": "assets/img/rna/p001.jpg", "anim": null, "fig": "", "points": ["①2006年诺奖授予Fire和Mello", "②奖励发现RNAi（双链RNA引发基因沉默）", "③RNA拼接和编辑增加多样性、消除突变、促进进化"], "check": null, "cards": null}, {"i": 1, "sec": "RNA的生物合成和转录后加工", "title": "中心法则总览 (p2)", "notes": "中心法则：DNA→转录→RNA前体→加工→成熟RNA；\u000bRNA→复制→RNA(RNA病毒)；\u000bRNA→逆转录→DNA。\u000b本章聚焦RNA生物合成(转录)及转录后加工，并涉及RNA复制和逆转录。", "page": 2, "level": "掌握", "img": "assets/img/rna/p002.jpg", "anim": null, "fig": "", "points": ["①RNA复制：RNA指导下合成RNA", "②RNA复制酶以RNA为模板、4种NTP为底物", "③聚合方向5'→3'；涉及Qβ噬菌体、病毒、新冠"], "check": null, "cards": null}, {"i": 2, "sec": "RNA的生物合成和转录后加工", "title": "第一节 DNA指导下RNA的合成 (p3-p4) (p3)", "notes": "第一节 DNA指导下RNA的合成。\u000b转录(transcription)：DNA指导下RNA的合成。\u000b内容：不对称转录→转录单位→启动子→终止子→原核/真核RNA合成分子机制→转录抑制剂。", "page": 3, "level": "掌握", "img": "assets/img/rna/p003.jpg", "anim": null, "fig": "", "points": ["①Qβ为+ssRNA小噬菌体，4500nt，正二十面体", "②复制酶4亚基：β催化(病毒编码)，αγδ由宿主提供", "③α=S1，γ=EF-Tu，δ=EF-Ts", "④复制经-RNA中间体，滚环式合成+RNA"], "check": null, "cards": null}, {"i": 3, "sec": "RNA的生物合成和转录后加工", "title": "不对称转录-编码链与模板链 (p5-p6) (p4)", "notes": "一、不对称转录。\u000b编码链(coding strand,+链)：与转录出的RNA顺序相同的链(仅T代替U)。\u000b模板链(template strand,-链)：为RNA提供转录模板的链。\u000b转录时DNA双链不是同时作模板，只有一条链作模板。", "page": 4, "level": "掌握", "img": "assets/img/rna/p004.jpg", "anim": null, "fig": "", "points": ["①RNA直接作模板：+RNA、-RNA、±RNA、++逆转录病毒", "②RNA→DNA→RNA为逆转录途径", "③复制均不对称，先合成互补链", "④+RNA病毒mRNA可直接翻译"], "check": null, "cards": null}, {"i": 4, "sec": "RNA的生物合成和转录后加工", "title": "不对称转录的特点 (p7)", "notes": "二、不对称转录特点：①不是所有基因的编码链都位于DNA同一条链上(不同基因的模板链不同)；\u000b②基因转录有选择性——非全部DNA都转录，特定基因按需开放/关闭，具复杂调控机制。", "page": 7, "level": "掌握", "img": "assets/img/rna/p007.jpg", "anim": null, "fig": "", "points": ["①不同基因模板链可在不同链上", "②并非全部DNA都转录", "③基因按需开放/关闭", "④转录受复杂调控机制控制"], "check": null, "cards": null}, {"i": 5, "sec": "RNA的生物合成和转录后加工", "title": "转录单位 (p8)", "notes": "三、转录单位：RNA转录起始于DNA模板特定位点，在另一位点终止，此转录区域称转录单位。\u000b原核：多顺反子(一个转录单位含多个基因→mRNA→多种蛋白质)。\u000b真核：单顺反子(一个转录单位含1个基因→1种蛋白质)。", "page": 8, "level": "掌握", "img": "assets/img/rna/p008.jpg", "anim": null, "fig": "", "points": ["①转录单位：从起始位点到终止位点", "②原核：多顺反子，一单位多基因", "③真核：单顺反子，一单位一基因", "④原核mRNA可翻译多种蛋白质"], "check": null, "cards": null}, {"i": 6, "sec": "RNA的生物合成和转录后加工", "title": "启动子和转录因子 (p9-p10) (p7)", "notes": "四、启动子(promoter)：RNA聚合酶识别、结合和开始转录的一段DNA序列，具特定核苷酸顺序。\u000b转录因子(transcription factor)：RNA聚合酶起始转录需要的辅助因子(蛋白质)。\u000b启动子鉴定用Footprint analysis(足迹法)。", "page": 7, "level": "掌握", "img": "assets/img/rna/p007.jpg", "anim": null, "fig": "", "points": ["①逆转录：以RNA为模板合成DNA", "②又称RNA指导的DNA合成", "③中心法则的补充，RNA→DNA", "④产物为cDNA，可整合入基因组"], "check": null, "cards": null}, {"i": 7, "sec": "RNA的生物合成和转录后加工", "title": "DNA序列书写方式 (p11)", "notes": "DNA序列的书写方式(编码链)：转录起点标记为+1，上游(upstream)为负(-1,-2...)，下游(downstream)为正(+2,+3...)。\u000b5'→3'方向。\u000b启动子位于转录起点上游。", "page": 11, "level": "理解", "img": "assets/img/rna/p011.jpg", "anim": null, "fig": "", "points": ["①转录起点记为+1", "②上游为负，下游为正", "③序列按5'→3'方向书写", "④启动子位于起点上游"], "check": null, "cards": null}, {"i": 8, "sec": "RNA的生物合成和转录后加工", "title": "原核启动子结构 (p12-p13) (p9)", "notes": "1.原核生物启动子结构：识别区含两个6bp保守序列：Pribnow box(TATAAT,\u000b位于-10区,\u000b双链局部解开区)和TTGACA(-35区,\u000b提供RNA聚合酶全酶识别信号)。\u000b+1为转录起点(第1个核苷酸掺入位置)。", "page": 9, "level": "掌握", "img": "assets/img/rna/p009.jpg", "anim": null, "fig": "锥虫线粒体细胞色素氧化酶亚基II mRNA在移码位点附近插入4个额外U，由20S复合体（内切酶、尿苷酰转移酶、连接酶）完成，纠正移码。", "points": ["①RNA编辑改变RNA编码序列", "②类型：U插入/删除（guide RNA指导）、C/A/U插入", "③例：锥虫线粒体COX II mRNA插入4个U"], "check": null, "cards": null}, {"i": 9, "sec": "RNA的生物合成和转录后加工", "title": "真核启动子结构 (p14-p15) (p10)", "notes": "2.真核启动子三类：类别Ⅰ(RNA聚合酶Ⅰ转录,rRNA基因)：核心启动子+上游控制元件，需UBF1+SL1因子。\u000b类别Ⅱ(RNA聚合酶Ⅱ,mRNA)：TATA框、Inr、上游元件、应答元件。\u000b类别Ⅲ(RNA聚合酶Ⅲ,tRNA/5SRNA)：基因内启动子(A框/B框)或上游启动子。", "page": 10, "level": "掌握", "img": "assets/img/rna/p010.jpg", "anim": null, "fig": "", "points": ["①基因组为两条相同(+)RNA，5'端氢键相连", "②两端有R重复序列，5'帽子、3'polyA", "③宿主tRNA作逆转录引物，7000-10000nt", "④三基因gag、pol、env，部分含癌基因"], "check": null, "cards": null}, {"i": 10, "sec": "RNA的生物合成和转录后加工", "title": "类别II启动子元件 (p16-p18) (p11)", "notes": "类别Ⅱ启动子(RNA聚合酶Ⅱ)顺式作用元件：起始子(Inr,\u000b+1)、TATA框(7bp,\u000b-25~-30bp处)、上游元件(CAAT框、GC框、八聚体框)、应答元件(GRE、HRE等)。\u000b通用转录因子TFⅡX共6种(TFⅡD/A/B/F/E/H)。\u000bTATA框是前起始复合物主要装配点。", "page": 11, "level": "掌握", "img": "assets/img/rna/p011.jpg", "anim": null, "fig": "图示逆转录全过程：从病毒RNA出发，经杂交分子、双链DNA，最终整合入宿主染色体，注意各酶（逆转录酶、RNase H）的作用顺序。", "points": ["①病毒RNA进入宿主，逆转录酶以tRNA为引物合成DNA", "②形成RNA-cDNA杂交分子，RNase H水解RNA链", "③DNA聚合酶合成双链DNA，整合为前病毒", "④前病毒随宿主染色体复制转录，完成逆转录周期"], "check": null, "cards": null}, {"i": 11, "sec": "RNA的生物合成和转录后加工", "title": "终止子和终止因子 (p19-p21) (p12)", "notes": "五、终止子(terminator)：提供转录终止信号的DNA序列。\u000b原核终止子在终止点前有回文结构→RNA形成发夹结构→聚合酶减慢/停止转录。\u000b两类：不依赖rho的终止子(简单终止子,发夹后接一串U)和依赖rho的终止子。\u000b终止因子：NusA/NusB/NusE/NusG等。", "page": 12, "level": "掌握", "img": "assets/img/rna/p012.jpg", "anim": null, "fig": "双链RNA被RNA内切酶切成约23nt的siRNA或70-90nt前体的miRNA，与RISC结合后特异性降解靶mRNA，实现基因沉默。", "points": ["①基因沉默分转录前（DNA修饰/异染色质化）和转录后水平", "②RNAi：双链RNA切成siRNA/miRNA", "③与RISC结合降解靶mRNA或抑制翻译"], "check": null, "cards": null}, {"i": 12, "sec": "RNA的生物合成和转录后加工", "title": "原核RNA合成机制总览 (p22-p23) (p13)", "notes": "五、原核RNA合成的分子机制。\u000b部位：核区。\u000b模板：双链DNA模板链。\u000b原料：NTP(N=A/G/C/U)。\u000b反应式：nNTP→(NMP)n+nPPi(DNA指导的RNA聚合酶,Mg2+)。\u000bRNA聚合酶特点：需4种NTP、需DNA模板、聚合方向5'→3'、不需引物、无外切酶(校对有限)。", "page": 13, "level": "掌握", "img": "assets/img/rna/p013.jpg", "anim": null, "fig": "", "points": ["①RNase P的RNA单独具催化活性", "②四膜虫rRNA自我拼接证明RNA可催化", "③RNA具催化功能称核酶(ribozyme)", "④tRNA含假尿苷、甲基化碱基等修饰"], "check": null, "cards": null}], "mcq": [{"id": "rna_mcq_1", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "转录(transcription)的定义是什么？", "o": ["A. DNA→蛋白质", "B. DNA指导下RNA的合成", "C. RNA→DNA", "D. RNA→蛋白质"], "a": "B", "e": "转录=DNA指导下RNA的合成。逆转录=RNA指导下DNA合成。翻译=RNA指导蛋白质合成。", "kp": "rna_s0_6"}, {"id": "rna_mcq_2", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "不对称转录中,与转录出的RNA顺序相同的链是？", "o": ["A. 模板链", "B. 编码链(+链,仅T代替U)", "C. 引物链", "D. 反义链"], "a": "B", "e": "编码链(+链)与RNA顺序相同(T→U)；模板链(-链)为RNA提供转录模板。", "kp": "rna_s0_3"}, {"id": "rna_mcq_3", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "原核生物的转录单位通常是？", "o": ["A. 单顺反子", "B. 多顺反子(多个基因→多种蛋白质)", "C. 无顺反子", "D. 只含rRNA"], "a": "B", "e": "原核为多顺反子(一个转录单位含多个基因)；真核为单顺反子(一个基因)。", "kp": "rna_s0_5"}, {"id": "rna_mcq_4", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "启动子(promoter)的定义是什么？", "o": ["A. 终止信号", "B. RNA聚合酶识别、结合和开始转录的DNA序列", "C. 翻译起点", "D. 复制起点"], "a": "B", "e": "启动子是RNA聚合酶识别结合起始转录的DNA序列。转录因子是起始转录所需的辅助蛋白。", "kp": "rna_s0_6"}, {"id": "rna_mcq_5", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "原核启动子Pribnow box位于什么位置？", "o": ["A. -35区", "B. -10区(TATAAT)", "C. +1区", "D. -75区"], "a": "B", "e": "Pribnow box(TATAAT)在-10区,是双链局部解开区。TTGACA在-35区,提供全酶识别信号。", "kp": "rna_s0_8"}, {"id": "rna_mcq_6", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "真核生物中负责转录mRNA的RNA聚合酶是？", "o": ["A. RNA聚合酶Ⅰ", "B. RNA聚合酶Ⅱ", "C. RNA聚合酶Ⅲ", "D. 三者均可"], "a": "B", "e": "PolⅡ转录mRNA/大多数snRNA(对α-鹅膏蕈碱敏感)；PolⅠ转录rRNA；PolⅢ转录tRNA/5SRNA。", "kp": "rna_s0_0"}, {"id": "rna_mcq_7", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "RNA聚合酶催化链延伸的方向是？", "o": ["A. 3'→5'", "B. 5'→3'", "C. 双向", "D. 随机"], "a": "B", "e": "RNA聚合酶沿5'→3'方向聚合，不需引物，无校对(外切酶)活性。", "kp": "rna_s0_12"}, {"id": "rna_mcq_8", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "原核RNA聚合酶中识别启动子的是哪个亚基？", "o": ["A. α", "B. β", "C. σ因子", "D. ω"], "a": "C", "e": "σ因子(起始亚基)识别启动子促进转录起始。核心酶α2ββ'催化链延长。", "kp": "rna_s0_12"}, {"id": "rna_mcq_9", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "转录起始时,新生RNA链5'端通常是什么？", "o": ["A. pppU", "B. pppA或pppG(第一个核苷酸通常ATP/GTP)", "C. OH", "D. 帽子"], "a": "B", "e": "转录第一个核苷酸通常是ATP或GTP,新生链5'端为pppA或pppG(三磷酸保留)。", "kp": "rna_s0_0"}, {"id": "rna_mcq_10", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "依赖rho因子的转录终止中,rho蛋白的活性？", "o": ["A. 聚合酶活性", "B. NTP酶活力+RNA-DNA解螺旋酶活力", "C. 连接酶", "D. 甲基化酶"], "a": "B", "e": "rho因子具NTP酶+RNA-DNA解螺旋酶活力，解开RNA-DNA杂交体终止转录。", "kp": "rna_s0_11"}], "judge": [], "fill": [{"id": "rna_fill_1", "modI": 0, "q": "转录是以________为模板合成RNA的过程,催化该过程的酶是________。", "a": "DNA(模板链),RNA聚合酶(DNA指导的RNA聚合酶)", "kp": "rna_s0_0"}, {"id": "rna_fill_2", "modI": 0, "q": "不对称转录中,与RNA顺序相同的链称________,提供转录模板的链称________。", "a": "编码链(+链),模板链(-链)", "kp": "rna_s0_3"}, {"id": "rna_fill_3", "modI": 0, "q": "原核启动子-10区称________(序列TATAAT),-35区序列是________,提供RNA聚合酶全酶识别信号。", "a": "Pribnow box,TTGACA", "kp": "rna_s0_8"}, {"id": "rna_fill_4", "modI": 0, "q": "原核RNA聚合酶核心酶是________,识别启动子的亚基是________。", "a": "α2ββ',σ因子", "kp": "rna_s0_12"}, {"id": "rna_fill_5", "modI": 0, "q": "RNA聚合酶催化方向是________,________(需要/不需要)引物,________(有/无)校对活性。", "a": "5'→3',不需要,无", "kp": "rna_s0_12"}], "short": [{"id": "rna_short_1", "modI": 0, "q": "简述原核生物RNA合成的转录过程(模板识别、起始、延伸、终止)。", "a": "【模板识别】\u000bRNA聚合酶在σ因子协助下结合到启动子上，DNA双链局部打开形成转录泡。\u000b\u000b【转录起始】\u000b①RNA聚合酶催化合成最初2~9个核苷酸(第一个通常ATP/GTP，新生链5'端pppA或pppG)\u000b②σ因子脱离核心酶\u000b\u000b【延伸】\u000b核心酶α2ββ'催化RNA链5'→3'延长\u000b\u000b【终止】\u000b①RNA聚合酶感知终止信号，NusA识别终止子→转录终止，RNA链释放\u000b②核心酶自模板脱落，重新与σ因子结合参与下次转录\u000b③依赖ρ的终止：ρ因子(NTP酶+解螺旋酶)解开RNA-DNA杂交体\u000b\u000b【关键】\u000b核心酶(α2ββ')负责延长，σ因子负责起始识别。", "kp": "rna_s0_12"}], "calc": [{"id": "rna_calc_2", "modI": 0, "q": "论述转录与DNA复制的异同。", "a": "转录与复制都是模板指导的聚合反应,但在模板、酶、产物、保真性等方面有本质区别", "steps": "【相同点】\u000b①都以DNA为模板\u000b②都按碱基互补配对原则\u000b③链延伸方向都是5'→3'\u000b④都需核苷三磷酸为底物\u000b⑤都形成磷酸二酯键\u000b\u000b【不同点】\u000b①模板:复制DNA两条链都作模板;转录仅模板链作模板(不对称)\u000b②酶:复制DNA聚合酶(需引物有校对);转录RNA聚合酶(不需引物无校对)\u000b③底物:复制dNTP;转录NTP\u000b④产物:复制DNA;转录RNA(mRNA/rRNA/tRNA)\u000b⑤保真性:复制高(10^-9~10^-10);转录较低(10^-4)\u000b⑥范围:复制全基因组;转录选择性\u000b⑦引物:复制需RNA引物;转录不需引物\u000b\u000b【总结】\u000b复制保真性高、全基因组、有校对(遗传信息稳定传递)\u000b转录选择性、无校对、可反复进行(基因表达调控)", "kp": "rna_s0_2"}], "term": [{"id": "rna_term_1", "modI": 0, "term": "转录(Transcription)", "def": "①以DNA为模板、按碱基互补原则合成RNA的过程，即DNA指导下RNA的合成（定义）。②由RNA聚合酶(DNA指导的RNA聚合酶)催化（酶）。③需NTP为底物，方向5'→3'，不需引物（特点）。④是遗传信息从DNA流向RNA的过程，是基因表达的第一步（意义）。", "kps": "①定义(2分)②酶(1分)③特点(1分)④意义(1分)", "kp": "rna_s0_6"}, {"id": "rna_term_2", "modI": 0, "term": "不对称转录", "def": "①转录时DNA双链不是同时作模板，只有一条链作模板的转录方式（定义）。②编码链(+链)：与RNA顺序相同的链(仅T代U)（编码链）。③模板链(-链)：为RNA提供模板的链（模板链）。④不同基因的模板链可位于DNA不同链上，基因转录有选择性（特点）。", "kps": "①定义(2分)②编码链(1分)③模板链(1分)④选择性(1分)", "kp": "rna_s0_3"}, {"id": "rna_term_3", "modI": 0, "term": "编码链/模板链", "def": "①编码链(coding strand,+链)：与转录出的RNA顺序相同的一条链(仅T代替U)（编码链）。②模板链(template strand,-链)：为RNA提供转录模板的链（模板链）。③RNA按碱基互补原则以模板链为模板合成，故RNA序列与编码链一致、与模板链互补（关系）。", "kps": "①编码链定义(2分)②模板链定义(2分)③互补关系(1分)", "kp": "rna_s0_3"}, {"id": "rna_term_4", "modI": 0, "term": "转录单位", "def": "①RNA转录起始于DNA模板特定位点、在另一位点终止，此转录区域称转录单位（定义）。②原核：多顺反子(一个转录单位含多个基因→多种蛋白质)（原核）。③真核：单顺反子(一个转录单位含1个基因→1种蛋白质)（真核）。", "kps": "①定义(2分)②原核多顺反子(1分)③真核单顺反子(2分)", "kp": "rna_s0_5"}, {"id": "rna_term_5", "modI": 0, "term": "启动子(Promoter)", "def": "①RNA聚合酶识别、结合和开始转录的一段DNA序列，具特定核苷酸顺序（定义）。②原核启动子含-10区(Pribnow box,TATAAT)和-35区(TTGACA)（原核）。③真核启动子分Ⅰ/Ⅱ/Ⅲ三类，Ⅱ类含TATA框、起始子等（真核）。④启动子决定转录起始的位置和效率（功能）。", "kps": "①定义(2分)②原核结构(1分)③真核结构(1分)④功能(1分)", "kp": "rna_s0_6"}, {"id": "rna_term_6", "modI": 0, "term": "Pribnow盒(Pribnow Box)", "def": "①原核生物启动子-10区的一段6bp保守序列(TATAAT)（定义）。②是RNA聚合酶结合后DNA双链局部解开的区域（功能）。③与-35区TTGACA(提供RNA聚合酶全酶识别信号)共同构成原核启动子识别区（结构）。", "kps": "①定义(2分)②-10区位置(1分)③功能(1分)④与-35区关系(1分)", "kp": "rna_s0_8"}, {"id": "rna_term_7", "modI": 0, "term": "终止子(Terminator)", "def": "①提供转录终止信号的DNA序列（定义）。②原核终止子在终止点前有回文结构→RNA形成发夹结构→聚合酶减慢/停止转录（机制）。③两类：不依赖rho的终止子(简单终止子)和依赖rho的终止子（分类）。", "kps": "①定义(2分)②发夹结构机制(2分)③两类(1分)", "kp": "rna_s0_11"}, {"id": "rna_term_8", "modI": 0, "term": "ρ因子(Rho Factor)", "def": "①参与原核生物依赖rho的转录终止的终止因子（定义）。②具NTP酶活力和RNA-DNA解螺旋酶活力（活性）。③沿RNA链3'→5'移动，在终止位点解开RNA-DNA杂交体→释放RNA（机制）。", "kps": "①定义(2分)②两种活力(1分)③终止机制(2分)", "kp": "rna_s0_6"}, {"id": "rna_term_9", "modI": 0, "term": "RNA聚合酶全酶/核心酶", "def": "①原核RNA聚合酶全酶由α2ββ'σ五个亚基组成(含Zn2+)（全酶）。②核心酶α2ββ'：催化RNA链延长（核心酶）。③σ因子(起始亚基)：识别启动子，促进转录起始（σ因子）。④起始后σ脱离，核心酶延伸（过程）。", "kps": "①全酶组成(2分)②核心酶功能(1分)③σ因子功能(1分)④起始后σ脱离(1分)", "kp": "rna_s0_12"}, {"id": "rna_term_12", "modI": 0, "term": "转录后加工(Post-transcriptional Processing)", "def": "①RNA前体转变为成熟RNA的过程（定义）。②包括：切割、修剪、添加、修饰和异构化、拼接、编辑、再编码（类型）。③真核mRNA前体加工：5'加帽、3'加尾、拼接（真核mRNA）。④rRNA/tRNA前体也需加工(甲基化、切割、修饰等)（其他）。", "kps": "①定义(2分)②加工类型(1分)③真核mRNA加工(1分)④rRNA/tRNA(1分)", "kp": "rna_s0_6"}, {"id": "rna_term_24", "modI": 0, "term": "RNA复制酶(RNA Replicase)", "def": "①以RNA为模板、催化RNA合成的酶(RNA指导下RNA合成)（定义）。②以4种NTP为底物，聚合方向5'→3'（特点）。③例：噬菌体Qβ复制酶(β亚基催化,α/γ/δ来自宿主)（实例）。④是RNA病毒复制的关键酶（意义）。", "kps": "①定义(2分)②特点(1分)③Qβ实例(1分)④意义(1分)", "kp": "rna_s0_0"}, {"id": "rna_term_25", "modI": 0, "term": "逆转录(Reverse Transcription)", "def": "①以RNA为模板、按RNA中核苷酸顺序合成DNA的过程(RNA指导的DNA合成)（定义）。②由逆转录酶催化（酶）。③逆转录酶兼有RNA指导DNA聚合酶、DNA指导DNA聚合酶、核糖核酸酶H三种活力（酶活力）。④是逆转录病毒复制的关键步骤（意义）。", "kps": "①定义(2分)②酶(1分)③三种活力(1分)④意义(1分)", "kp": "rna_s0_6"}]}, {"i": 1, "name": "模块二：真核转录与抑制剂", "slides": [{"i": 0, "sec": "RNA的生物合成和转录后加工", "title": "RNA聚合酶结构 (p24-p25) (p1)", "notes": "原核RNA聚合酶：Mr 460000，5个亚基(α2ββ'σ)，含Zn2+。\u000bα2ββ'(核心酶)催化RNA链延长；\u000bσ(起始亚基)识别启动子促进转录起始；\u000bω功能未知。\u000b转录泡(transcription bubble)：转录时DNA局部解开的区域。", "page": 1, "level": "掌握", "img": "assets/img/rna/p001.jpg", "anim": null, "fig": "", "points": ["①2006年诺奖授予Fire和Mello", "②奖励发现RNAi（双链RNA引发基因沉默）", "③RNA拼接和编辑增加多样性、消除突变、促进进化"], "check": null, "cards": null}, {"i": 1, "sec": "RNA的生物合成和转录后加工", "title": "转录过程-模板识别/起始/延伸 (p26)", "notes": "(二)转录过程。\u000b1.模板识别：RNA聚合酶在σ因子协助下结合启动子，DNA双链局部打开形成转录泡。\u000b2.转录起始：①RNA聚合酶合成最初2~9个核苷酸(第一个通常ATP/GTP，新生链5'端为pppA或pppG)；\u000b②σ因子脱离核心酶。\u000b3.延伸：核心酶α2ββ'催化RNA链5'→3'延长。", "page": 26, "level": "掌握", "img": "assets/img/rna/p026.jpg", "anim": null, "fig": "", "points": ["①模板识别：σ协助结合启动子，形成转录泡", "②起始：合成最初2~9个核苷酸，5'端pppA/pppG", "③起始后σ因子脱离核心酶", "④延伸：核心酶α2ββ'催化5'→3'延长"], "check": null, "cards": null}, {"i": 2, "sec": "RNA的生物合成和转录后加工", "title": "转录过程-终止 (p27-p30) (p3)", "notes": "4.终止：RNA聚合酶感知终止信号，NusA识别终止子→转录终止，RNA链释放。\u000b核心酶α2ββ'自模板脱落，重新与σ因子结合参与下次转录。\u000b依赖ρ的终止需ρ蛋白(NTP酶活力+RNA-DNA解螺旋酶活力)解开RNA-DNA杂交体。", "page": 3, "level": "掌握", "img": "assets/img/rna/p003.jpg", "anim": null, "fig": "", "points": ["①Qβ为+ssRNA小噬菌体，4500nt，正二十面体", "②复制酶4亚基：β催化(病毒编码)，αγδ由宿主提供", "③α=S1，γ=EF-Tu，δ=EF-Ts", "④复制经-RNA中间体，滚环式合成+RNA"], "check": null, "cards": null}, {"i": 3, "sec": "RNA的生物合成和转录后加工", "title": "ρ因子在终止中的作用 (p28)", "notes": "ρ因子具NTP酶活力和RNA-DNA解螺旋酶活力，沿RNA链3'→5'移动追赶RNA聚合酶，在终止位点解开RNA-DNA杂交体→释放RNA。\u000b依赖ρ因子的转录终止。", "page": 28, "level": "理解", "img": "assets/img/rna/p028.jpg", "anim": null, "fig": "", "points": ["①ρ因子有NTP酶和RNA-DNA解螺旋酶活力", "②沿RNA链3'→5'追赶RNA聚合酶", "③在终止位点解开RNA-DNA杂交体释放RNA", "④属依赖ρ因子的转录终止方式"], "check": null, "cards": null}, {"i": 4, "sec": "RNA的生物合成和转录后加工", "title": "真核RNA聚合酶 (p31)", "notes": "六、真核生物RNA的合成。\u000b(一)RNA聚合酶：RNA聚合酶Ⅰ(核仁,5.8S/18S/28S rRNA前体,对α-鹅膏蕈碱不敏感)；\u000bRNA聚合酶Ⅱ(核浆,mRNA/大多数snRNA,敏感)；\u000bRNA聚合酶Ⅲ(核浆,tRNA/5SRNA等小RNA,中等敏感)。\u000bMr 500000，8-14个亚基，含Zn2+。", "page": 31, "level": "掌握", "img": "assets/img/rna/p031.jpg", "anim": null, "fig": "", "points": ["①真核有PolⅠ、Ⅱ、Ⅲ三种RNA聚合酶", "②PolⅠ在核仁合成rRNA前体，不敏感", "③PolⅡ在核浆合成mRNA，敏感", "④PolⅢ合成tRNA/5S rRNA，中等敏感"], "check": null, "cards": null}, {"i": 5, "sec": "RNA的生物合成和转录后加工", "title": "真核转录-装配与起始 (p32-p33) (p6)", "notes": "(二)合成过程(装配/起始/延长/终止)。\u000b1.装配：真核RNA聚合酶不能识别启动子，需与通用转录因子装配成前起始复合物(PIC)。\u000bⅡ类启动子至少6种通用转录因子。\u000b2.起始：前起始复合物作用下DNA双链分开形成开放复合物，PolⅡ开始合成。\u000bTFⅡD识别TATA框、TFⅡA稳定、TFⅡB引进PolⅡ等。", "page": 6, "level": "掌握", "img": "assets/img/rna/p006.jpg", "anim": null, "fig": "", "points": ["①SARS-CoV-2为β属冠状病毒，+ssRNA 29891nt", "②与SARS相似性79.5%，编码9860aa", "③结构蛋白S/E/M/N；Nsp12=RdRp，Nsp13解旋酶", "④S结合ACE2→膜融合→释放RNA→复制出芽"], "check": null, "cards": null}, {"i": 6, "sec": "RNA的生物合成和转录后加工", "title": "真核转录-延伸与终止 (p34)", "notes": "3.延伸：起始后PolⅡ被磷酸化，构象改变脱离起始复合物，沿模板滑动催化RNA链延伸。\u000b4.终止：真核RNA原初转录物3'端很快被加工，终止序列难研究，机制尚不清楚。\u000bPolⅡ去磷酸化参与下一轮。", "page": 34, "level": "理解", "img": "assets/img/rna/p034.jpg", "anim": null, "fig": "", "points": ["①起始后PolⅡ磷酸化、构象改变脱离起始复合物", "②沿模板滑动催化RNA链延伸", "③真核终止序列难研究，机制尚不清楚", "④原初转录物3'端很快被加工"], "check": null, "cards": null}, {"i": 7, "sec": "RNA的生物合成和转录后加工", "title": "转录作用的抑制剂 (p35)", "notes": "七、转录抑制剂。\u000b1.核苷酸合成抑制剂(嘌呤/嘧啶类似物、氨基酸类似物、叶酸类似物)。\u000b2.DNA模板功能抑制剂：放线菌素D(插入DNA双链碱基对之间)、嵌入染料(溴化乙锭)。\u000b3.RNA聚合酶抑制剂：利福平(抑制细菌RNA聚合酶β亚基)、α-鹅膏蕈碱(抑制真核RNA聚合酶Ⅱ)。", "page": 35, "level": "掌握", "img": "assets/img/rna/p035.jpg", "anim": null, "fig": "", "points": ["①核苷酸合成抑制剂：嘌呤/嘧啶/叶酸类似物", "②放线菌素D插入DNA双链间抑制模板功能", "③利福平抑制细菌RNA聚合酶β亚基", "④α-鹅膏蕈碱抑制真核RNA聚合酶Ⅱ"], "check": null, "cards": null}, {"i": 8, "sec": "RNA的生物合成和转录后加工", "title": "第二节 RNA的转录后加工 (p36-p37) (p9)", "notes": "第二节 RNA的转录后加工。\u000b转录后加工(post-transcriptional processing)过程：切割、修剪、添加、修饰和异构化、拼接、编辑、再编码。\u000b内容：rRNA/tRNA/mRNA前体加工、RNA编辑、RNA功能多样性。", "page": 9, "level": "掌握", "img": "assets/img/rna/p009.jpg", "anim": null, "fig": "锥虫线粒体细胞色素氧化酶亚基II mRNA在移码位点附近插入4个额外U，由20S复合体（内切酶、尿苷酰转移酶、连接酶）完成，纠正移码。", "points": ["①RNA编辑改变RNA编码序列", "②类型：U插入/删除（guide RNA指导）、C/A/U插入", "③例：锥虫线粒体COX II mRNA插入4个U"], "check": null, "cards": null}, {"i": 9, "sec": "RNA的生物合成和转录后加工", "title": "原核rRNA前体加工 (p38-p39) (p10)", "notes": "一、rRNA前体加工。\u000b1.原核E.coli：7个rRNA转录单位，每个由16S/23S/5S rRNA基因+1或几个tRNA基因组成(rRNA基因为多拷贝)。\u000b加工：①甲基化(位置常在核糖2'-OH，约30个)；\u000b②切割和修剪(RNaseⅢ/Rnase P/Rnase E)。", "page": 10, "level": "掌握", "img": "assets/img/rna/p010.jpg", "anim": null, "fig": "", "points": ["①基因组为两条相同(+)RNA，5'端氢键相连", "②两端有R重复序列，5'帽子、3'polyA", "③宿主tRNA作逆转录引物，7000-10000nt", "④三基因gag、pol、env，部分含癌基因"], "check": null, "cards": null}, {"i": 10, "sec": "RNA的生物合成和转录后加工", "title": "真核rRNA前体加工 (p40-p41) (p11)", "notes": "2.真核rRNA前体加工：rRNA基因拷贝数多(几十~几千)，成簇排列，16-18S/5.8S/26-28S组成一个转录单位，以间隔区分。\u000b与原核相似但甲基化程度更高(>100个甲基化)。\u000b甲基化、假尿苷化、切割由核仁小RNA(snoRNA)指导。", "page": 11, "level": "掌握", "img": "assets/img/rna/p011.jpg", "anim": null, "fig": "图示逆转录全过程：从病毒RNA出发，经杂交分子、双链DNA，最终整合入宿主染色体，注意各酶（逆转录酶、RNase H）的作用顺序。", "points": ["①病毒RNA进入宿主，逆转录酶以tRNA为引物合成DNA", "②形成RNA-cDNA杂交分子，RNase H水解RNA链", "③DNA聚合酶合成双链DNA，整合为前病毒", "④前病毒随宿主染色体复制转录，完成逆转录周期"], "check": null, "cards": null}, {"i": 11, "sec": "RNA的生物合成和转录后加工", "title": "tRNA前体加工 (p42-p43) (p12)", "notes": "二、tRNA前体加工：①核酸内切酶在tRNA两端切断(RNase P切5'端、RNase F切3'端)；\u000b②核酸外切酶(RNase D)从3'端逐个修剪；\u000b③3'端添加CCAOH(tRNA核苷酰转移酶)；\u000b④核苷酸修饰和异构化；\u000b⑤剪接去除内含子(某些真核)。\u000bRNase P是核酸内切酶，由蛋白质+RNA(M1RNA)组成。", "page": 12, "level": "掌握", "img": "assets/img/rna/p012.jpg", "anim": null, "fig": "双链RNA被RNA内切酶切成约23nt的siRNA或70-90nt前体的miRNA，与RISC结合后特异性降解靶mRNA，实现基因沉默。", "points": ["①基因沉默分转录前（DNA修饰/异染色质化）和转录后水平", "②RNAi：双链RNA切成siRNA/miRNA", "③与RISC结合降解靶mRNA或抑制翻译"], "check": null, "cards": null}, {"i": 12, "sec": "RNA的生物合成和转录后加工", "title": "RNase P和核酶 (p44-p45) (p13)", "notes": "RNase P的RNA(M1RNA)单独具催化活性；\u000b四膜虫rRNA前体自我拼接(L19RNA，395核苷酸线状RNA)证明RNA具催化功能——发现核酶(ribozyme)。\u000btRNA含多种修饰碱基(假尿苷、甲基化碱基等)。", "page": 13, "level": "掌握", "img": "assets/img/rna/p013.jpg", "anim": null, "fig": "", "points": ["①RNase P的RNA单独具催化活性", "②四膜虫rRNA自我拼接证明RNA可催化", "③RNA具催化功能称核酶(ribozyme)", "④tRNA含假尿苷、甲基化碱基等修饰"], "check": null, "cards": null}], "mcq": [{"id": "rna_mcq_11", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "α-鹅膏蕈碱(α-amanitin)抑制什么？", "o": ["A. 细菌RNA聚合酶β亚基", "B. 真核RNA聚合酶Ⅱ", "C. DNA聚合酶", "D. 核糖体"], "a": "B", "e": "α-鹅膏蕈碱抑制真核PolⅡ。利福平抑制细菌RNA聚合酶β亚基。", "kp": "rna_s1_7"}, {"id": "rna_mcq_12", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "放线菌素D的转录抑制机制？", "o": ["A. 抑制聚合酶", "B. 插入DNA双链碱基对之间,抑制模板功能", "C. 抑制核苷酸合成", "D. 降解RNA"], "a": "B", "e": "放线菌素D嵌入DNA双链碱基对之间→阻断转录。溴化乙锭也是嵌入染料。", "kp": "rna_s1_7"}, {"id": "rna_mcq_13", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "真核mRNA前体(hnRNA)加工不包括什么？", "o": ["A. 5'端加帽", "B. 3'端加polyA尾", "C. 拼接(去除内含子)", "D. 添加CCAOH末端"], "a": "D", "e": "添加CCAOH是tRNA的加工。hnRNA加工：加帽、加尾、拼接、甲基化。", "kp": "rna_s1_10"}, {"id": "rna_mcq_14", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "真核mRNA的5'帽结构是？", "o": ["A. m7G5'ppp5'NmpNp-", "B. polyA", "C. CCA", "D. 假尿苷"], "a": "A", "e": "帽结构m7G5'ppp5'NmpNp-。polyA是3'尾。CCA是tRNA 3'端。", "kp": "rna_s1_4"}, {"id": "rna_mcq_15", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "polyA尾的加尾信号是什么？", "o": ["A. TATA", "B. AAUAAA", "C. GU", "D. AG"], "a": "B", "e": "加尾信号AAUAAA，在其3'端11~30nt处切断，PolyA聚合酶加20~200个A。组蛋白mRNA无polyA尾。", "kp": "rna_s1_2"}, {"id": "rna_mcq_16", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "真核mRNA内含子的GU-AG规则是什么？", "o": ["A. 内含子5'端GU,3'端AG", "B. 内含子5'端AG,3'端GU", "C. 外显子GU-AG", "D. 启动子GU-AG"], "a": "A", "e": "GU-AG规则：真核mRNA前体内含子5'端GU、3'端AG，是拼接识别的重要保守序列。", "kp": "rna_s1_4"}, {"id": "rna_mcq_17", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "拼接体(spliceosome)主要由什么组成？", "o": ["A. 核糖体", "B. U1/U2/U4/U5/U6 snRNP和约50种蛋白质", "C. 端粒酶", "D. RNA聚合酶"], "a": "B", "e": "拼接体由U1、U2、U4-6 snRNP(含snRNA+蛋白)和约50种蛋白组成。", "kp": "rna_s1_8"}, {"id": "rna_mcq_18", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "RNA拼接中,分支点保守序列是什么？", "o": ["A. TATAAT", "B. UACUAAC", "C. AAUAAA", "D. GU"], "a": "B", "e": "分支点序列UACUAAC十分保守，其中未配对A的2'-OH亲核攻击5'拼接点(第一次转酯反应)。", "kp": "rna_s1_8"}, {"id": "rna_mcq_19", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "选择性拼接(alternative splicing)的含义？", "o": ["A. 基因突变", "B. 一个基因通过不同拼接方式产生不同mRNA和翻译产物", "C. RNA降解", "D. 转录终止"], "a": "B", "e": "选择性拼接使一个基因在不同细胞/发育阶段产生多种mRNA和蛋白，增加基因产物多样性。", "kp": "rna_s1_8"}, {"id": "rna_mcq_20", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "RNase P的催化本质是？", "o": ["A. 蛋白质", "B. RNA(M1RNA)具催化活性(核酶)", "C. 多糖", "D. 脂类"], "a": "B", "e": "RNase P由蛋白质+RNA组成，其RNA(M1RNA)单独具切割活性→核酶(ribozyme)。", "kp": "rna_s1_12"}], "judge": [], "fill": [{"id": "rna_fill_6", "modI": 1, "q": "真核RNA聚合酶Ⅰ转录________,RNA聚合酶Ⅱ转录________,RNA聚合酶Ⅲ转录________。", "a": "rRNA(5.8S/18S/28S),mRNA/大多数snRNA,tRNA/5SRNA等小RNA", "kp": "rna_s1_4"}, {"id": "rna_fill_13", "modI": 1, "q": "转录抑制剂中,利福平抑制________,α-鹅膏蕈碱抑制________,放线菌素D________。", "a": "细菌RNA聚合酶β亚基,真核RNA聚合酶Ⅱ,插入DNA双链碱基对之间", "kp": "rna_s1_7"}], "short": [{"id": "rna_short_2", "modI": 1, "q": "比较原核生物与真核生物转录的异同。", "a": "【相同点】\u000b①都是DNA指导的RNA合成\u000b②合成方向5'→3'，不需引物\u000b③都以DNA模板链为模板\u000b④都需启动子\u000b\u000b【不同点】\u000b①RNA聚合酶:原核1种(α2ββ'σ) vs 真核3种(PolⅠ/Ⅱ/Ⅲ)\u000b②启动子识别:原核σ因子直接识别 vs 真核需通用转录因子(TFⅡ)装配前起始复合物\u000b③转录单位:原核多顺反子 vs 真核单顺反子\u000b④部位:原核核区 vs 真核核内(转录翻译分开)\u000b⑤mRNA加工:原核mRNA一般不需加工 vs 真核hnRNA需加帽/加尾/拼接\u000b⑥转录与翻译:原核偶联 vs 真核分开\u000b⑦终止:原核有rho依赖/不依赖两类 vs 真核终止机制尚不清楚", "kp": "rna_s1_5"}, {"id": "rna_short_3", "modI": 1, "q": "简述真核生物RNA聚合酶Ⅱ的转录起始过程。", "a": "真核PolⅡ不能直接识别启动子，需通用转录因子装配前起始复合物(PIC)。\u000b\u000b【装配】\u000b①TFⅡD识别结合TATA框(TBP亚基)\u000b②TFⅡA稳定TFⅡD-TATA框结合\u000b③TFⅡB结合TBP，引进TFⅡF-PolⅡ\u000b④TFⅡF与PolⅡ结合，参与解链\u000b⑤TFⅡE引入TFⅡH\u000b⑥TFⅡH具解旋酶和激酶活性\u000b\u000b【起始】\u000b前起始复合物作用下DNA双链分开→开放复合物→PolⅡ开始合成RNA\u000b\u000b【延伸】\u000bPolⅡ被磷酸化(CTD)→构象改变→脱离起始复合物→沿模板滑动延伸\u000b\u000b【终止】\u000b机制尚不清楚；PolⅡ去磷酸化参与下一轮催化\u000b\u000b【关键】\u000b6种通用转录因子:TFⅡD/A/B/F/E/H", "kp": "rna_s1_4"}], "calc": [], "term": [{"id": "rna_term_10", "modI": 1, "term": "转录泡(Transcription Bubble)", "def": "①转录过程中，RNA聚合酶处DNA双链局部解开的区域（定义）。②是RNA合成的活性位点，RNA聚合酶在转录泡内催化RNA合成（功能）。③随转录沿模板移动（特点）。", "kps": "①定义(2分)②功能(2分)③移动(1分)", "kp": "rna_s1_0"}, {"id": "rna_term_26", "modI": 1, "term": "逆转录酶(Reverse Transcriptase)", "def": "①催化RNA→DNA合成的酶（定义）。②1970年Temin和Baltimore从致癌RNA病毒中发现，1975年诺贝尔奖（发现）。③兼三种活力：RNA指导DNA聚合酶、DNA指导DNA聚合酶、核糖核酸酶H（活力）。④需dNTP、模板和tRNA引物、Mg2+，方向5'→3'（条件）。⑤分子克隆核心工具酶(cDNA合成)（应用）。", "kps": "①定义(2分)②发现/诺贝尔(1分)③三种活力(1分)④应用(1分)", "kp": "rna_s1_8"}]}, {"i": 2, "name": "模块三：转录后加工(rRNA/tRNA/mRNA)", "slides": [{"i": 0, "sec": "RNA的生物合成和转录后加工", "title": "mRNA前体加工总览 (p46-p47) (p1)", "notes": "三、mRNA前体加工。\u000b原核mRNA一般不需加工(少数简单加工)。\u000b真核mRNA前体(核内不均一RNA,hnRNA)加工包括：①5'端加帽(m7G)；\u000b②3'端加polyA尾；\u000b③拼接(去除内含子)；\u000b④核苷酸甲基化(m6A)。", "page": 1, "level": "掌握", "img": "assets/img/rna/p001.jpg", "anim": null, "fig": "", "points": ["①2006年诺奖授予Fire和Mello", "②奖励发现RNAi（双链RNA引发基因沉默）", "③RNA拼接和编辑增加多样性、消除突变、促进进化"], "check": null, "cards": null}, {"i": 1, "sec": "RNA的生物合成和转录后加工", "title": "mRNA加帽 (p48)", "notes": "1.mRNA前体的加帽：帽结构m7G5'ppp5'NmpNp-。\u000bCap0型(大多数真核)、CapI型、CapII型。\u000b由磷酸酶、鸟苷酰转移酶、甲基转移酶催化(需S-腺苷Met)。\u000b帽功能：保护mRNA5'端、促进翻译起始。", "page": 48, "level": "掌握", "img": "assets/img/rna/p048.jpg", "anim": null, "fig": "", "points": ["①帽结构m7G5'ppp5'NmpNp-", "②分Cap0、CapI、CapII三型", "③磷酸酶、鸟苷酰转移酶、甲基转移酶催化", "④帽保护5'端并促进翻译起始"], "check": null, "cards": null}, {"i": 2, "sec": "RNA的生物合成和转录后加工", "title": "mRNA加尾 (p49)", "notes": "2.mRNA前体的加尾：在加尾信号AAUAAA的3'端11~30核苷酸处切断mRNA，内切酶+PolyA聚合酶聚合20~200个腺苷酸的poly(A)尾。\u000b酶复合物含特异因子、剪切因子、PolyA聚合酶等。\u000b组蛋白mRNA无poly(A)尾。", "page": 49, "level": "掌握", "img": "assets/img/rna/p049.jpg", "anim": null, "fig": "", "points": ["①加尾信号AAUAAA下游11~30nt处切断", "②PolyA聚合酶加20~200个A", "③组蛋白mRNA无poly(A)尾"], "check": null, "cards": null}, {"i": 3, "sec": "RNA的生物合成和转录后加工", "title": "RNA的拼接-四种方式 (p50-p52) (p4)", "notes": "3.RNA拼接(splicing)：去除内含子使外显子成连续序列。\u000b四种方式：①类型I自我拼接(鸟苷介导)；\u000b②类型II自我拼接(套索结构)；\u000b③真核mRNA拼接体拼接；\u000b④核tRNA酶促拼接。\u000b类型I见于低等真核核rRNA基因/细胞器基因。", "page": 4, "level": "掌握", "img": "assets/img/rna/p004.jpg", "anim": null, "fig": "", "points": ["①RNA直接作模板：+RNA、-RNA、±RNA、++逆转录病毒", "②RNA→DNA→RNA为逆转录途径", "③复制均不对称，先合成互补链", "④+RNA病毒mRNA可直接翻译"], "check": null, "cards": null}, {"i": 4, "sec": "RNA的生物合成和转录后加工", "title": "真核mRNA拼接-GU-AG规则 (p53-p57) (p5)", "notes": "真核hnRNA拼接(拼接体)：GU-AG规则——内含子5'端为GU，3'端为AG。\u000b分支点序列UACUAAC十分保守，其中未配对A的2'-OH亲核攻击5'拼接点。\u000bSnRNA(U1/U2/U4/U5/U6)与蛋白质形成SnRNP，引导拼接。", "page": 5, "level": "掌握", "img": "assets/img/rna/p005.jpg", "anim": null, "fig": "", "points": ["①SARS为单链(+)RNA，29724nt", "②5'帽子、3'polyA，似真核mRNA", "③结构蛋白S、E、M、N", "④RNA重组率高，病毒易变异"], "check": null, "cards": null}, {"i": 5, "sec": "RNA的生物合成和转录后加工", "title": "拼接体及拼接机制 (p58-p59) (p6)", "notes": "拼接体(spliceosome)：U1、U2、U4-6和约50种蛋白质组成的复合物。\u000b机制：U1结合5'拼接点，\u000bU2结合分支点，\u000bU4/U6+U5三聚体进入→U1/U4释放，\u000bU6结合5'拼接点与U2结合→分支点A的2'-OH攻击5'拼接点(第一次转酯反应)→U5使外显子靠近，\u000b5'外显子3'-OH攻击3'拼接点(第二次转酯反应)→外显子连接，\u000b内含子以套索形式释放。", "page": 6, "level": "掌握", "img": "assets/img/rna/p006.jpg", "anim": null, "fig": "", "points": ["①SARS-CoV-2为β属冠状病毒，+ssRNA 29891nt", "②与SARS相似性79.5%，编码9860aa", "③结构蛋白S/E/M/N；Nsp12=RdRp，Nsp13解旋酶", "④S结合ACE2→膜融合→释放RNA→复制出芽"], "check": null, "cards": null}, {"i": 6, "sec": "RNA的生物合成和转录后加工", "title": "卵清蛋白基因加工 (p60)", "notes": "卵清蛋白基因mRNA前体的加工：卵清蛋白基因含多个外显子和内含子，转录产生hnRNA，经拼接去除内含子形成成熟mRNA。\u000b展示了断裂基因的结构。", "page": 60, "level": "理解", "img": "assets/img/rna/p060.jpg", "anim": null, "fig": "图示卵清蛋白基因的断裂结构：外显子与内含子交替排列，转录后内含子被切除、外显子连接成成熟mRNA，可直观理解拼接过程。", "points": ["①卵清蛋白基因是断裂基因：含多个外显子和内含子", "②转录生成hnRNA前体", "③拼接去除内含子，形成成熟mRNA"], "check": null, "cards": null}, {"i": 7, "sec": "RNA的生物合成和转录后加工", "title": "选择性拼接 (p61-p63) (p8)", "notes": "选择性拼接(alternative splicing)：一个基因的转录产物在不同细胞/发育阶段/生理状态下，通过不同拼接方式得到不同mRNA和翻译产物。\u000b例：鼠降钙素mRNA前体有两个polyA位点，甲状腺产生降钙素，脑产生降钙素基因相关肽。\u000b意义：①拼接是进化结果；\u000b②基因表达调节的重要环节；\u000b③内含子存在利于进化(外显子对应蛋白结构域)。", "page": 8, "level": "掌握", "img": "assets/img/rna/p008.jpg", "anim": null, "fig": "", "points": ["①1964 Temin提出前病毒学说", "②1970 Temin与Baltimore发现逆转录酶", "③1975年获诺贝尔生理或医学奖", "④杜尔贝科证明DNA可嵌入基因组"], "check": null, "cards": null}, {"i": 8, "sec": "RNA的生物合成和转录后加工", "title": "RNA的编辑 (p64-p65) (p9)", "notes": "四、RNA编辑(editing)：改变RNA的编码序列。\u000b类型：U的插入与删除(guide RNA指导,锥虫线粒体mRNA)、C/A/U的插入等。\u000b例：锥虫线粒体细胞色素氧化酶亚基II mRNA，在移码位点附近插入4个额外U(20S复合体：核酸内切酶/末端尿苷酰转移酶/RNA连接酶)。", "page": 9, "level": "掌握", "img": "assets/img/rna/p009.jpg", "anim": null, "fig": "锥虫线粒体细胞色素氧化酶亚基II mRNA在移码位点附近插入4个额外U，由20S复合体（内切酶、尿苷酰转移酶、连接酶）完成，纠正移码。", "points": ["①RNA编辑改变RNA编码序列", "②类型：U插入/删除（guide RNA指导）、C/A/U插入", "③例：锥虫线粒体COX II mRNA插入4个U"], "check": null, "cards": null}, {"i": 9, "sec": "RNA的生物合成和转录后加工", "title": "RNA编辑-apoB与意义 (p66-p67) (p10)", "notes": "例：载脂蛋白apoB-100基因的RNA编辑(C→U)：CAA→UAA(终止密码)，肽链提前结束——肝产生apoB-100，小肠经编辑产生apoB-48。\u000bRNA编辑意义：①消除移码突变危害；\u000b②增加基因产物多样性；\u000b③使产物获得新结构功能；\u000b④基因调控的重要方式。", "page": 10, "level": "掌握", "img": "assets/img/rna/p010.jpg", "anim": null, "fig": "", "points": ["①基因组为两条相同(+)RNA，5'端氢键相连", "②两端有R重复序列，5'帽子、3'polyA", "③宿主tRNA作逆转录引物，7000-10000nt", "④三基因gag、pol、env，部分含癌基因"], "check": null, "cards": null}, {"i": 10, "sec": "RNA的生物合成和转录后加工", "title": "RNA功能多样性-催化与加工 (p68)", "notes": "五、RNA生物功能多样性。\u000b1.遗传信息翻译中起决定性作用(mRNA/rRNA/tRNA)。\u000b2.具重要催化功能(核酶)。\u000b3.转录后加工和修饰依赖小RNA及其蛋白复合物：snoRNA(参与rRNA加工)、SnRNA(参与hnRNA加工)、端粒酶RNA。", "page": 68, "level": "掌握", "img": "assets/img/rna/p068.jpg", "anim": null, "fig": "", "points": ["①mRNA/rRNA/tRNA在翻译中起决定作用", "②核酶具催化功能", "③snoRNA、SnRNA、端粒酶RNA参与加工修饰"], "check": null, "cards": null}, {"i": 11, "sec": "RNA的生物合成和转录后加工", "title": "RNAi与基因沉默 (p69-p70) (p12)", "notes": "4.对基因表达和细胞功能的调节：RNA干扰(RNAi)与基因沉默。\u000b基因沉默含转录前水平(DNA修饰/异染色质化)和转录后水平(靶mRNA被特异性降解或抑制翻译)。\u000bRNAi：双链RNA被RNA内切酶切成siRNA(~23nt)/miRNA(70-90nt前体)，与RISC(RNA诱导沉默复合物)结合降解靶mRNA。", "page": 12, "level": "掌握", "img": "assets/img/rna/p012.jpg", "anim": null, "fig": "双链RNA被RNA内切酶切成约23nt的siRNA或70-90nt前体的miRNA，与RISC结合后特异性降解靶mRNA，实现基因沉默。", "points": ["①基因沉默分转录前（DNA修饰/异染色质化）和转录后水平", "②RNAi：双链RNA切成siRNA/miRNA", "③与RISC结合降解靶mRNA或抑制翻译"], "check": null, "cards": null}], "mcq": [{"id": "rna_mcq_21", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "RNA编辑(editing)的含义？", "o": ["A. 剪接", "B. 改变RNA的编码序列(U插入/删除,C→U等)", "C. 加帽", "D. 加尾"], "a": "B", "e": "RNA编辑改变编码序列：如锥虫线粒体mRNA插入U、apoB mRNA C→U(终止密码)。", "kp": "rna_s2_8"}, {"id": "rna_mcq_22", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "载脂蛋白apoB-100基因RNA编辑(C→U)的结果？", "o": ["A. 延长蛋白", "B. CAA→UAA终止密码,小肠产生apoB-48", "C. 移码", "D. 无变化"], "a": "B", "e": "C→U使CAA(谷氨酰胺)→UAA(终止密码)，小肠肽链提前终止产生apoB-48。", "kp": "rna_s2_9"}, {"id": "rna_mcq_23", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "RNA干扰(RNAi)中,与siRNA/miRNA结合的复合物是？", "o": ["A. 拼接体", "B. RISC(RNA诱导沉默复合物)", "C. 核糖体", "D. 复制体"], "a": "B", "e": "siRNA/miRNA与RISC结合，指导降解靶mRNA或抑制翻译→基因沉默。", "kp": "rna_s2_11"}, {"id": "rna_mcq_24", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "2006年诺贝尔奖奖励的发现是？", "o": ["A. DNA复制", "B. RNAi(双链RNA引发的基因沉默)", "C. 逆转录酶", "D. 端粒酶"], "a": "B", "e": "2006年诺贝尔生理或医学奖授予Fire和Mello，奖励RNAi机制的发现。", "kp": "rna_s2_2"}, {"id": "rna_mcq_25", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "RNA复制酶(RNA replicase)的特点？", "o": ["A. 需DNA模板", "B. 以RNA为模板,以4种NTP为底物,5'→3'", "C. 需引物", "D. 有校对活性"], "a": "B", "e": "RNA复制酶以RNA为模板合成RNA(RNA→RNA)，5'→3'，不需DNA。", "kp": "rna_s2_3"}, {"id": "rna_mcq_26", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "噬菌体Qβ复制酶的催化亚基是？", "o": ["A. α", "B. β亚基(病毒编码,催化中心)", "C. γ", "D. δ"], "a": "B", "e": "Qβ复制酶β亚基(病毒编码)是催化中心；α(S1)、γ(EF-Tu)、δ(EF-Ts)来自宿主。", "kp": "rna_s2_10"}, {"id": "rna_mcq_27", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "逆转录(reverse transcription)的定义？", "o": ["A. DNA→RNA", "B. 以RNA为模板合成DNA", "C. RNA→RNA", "D. DNA→DNA"], "a": "B", "e": "逆转录=以RNA为模板，按RNA核苷酸顺序合成DNA(RNA指导的DNA合成)。", "kp": "rna_s2_7"}, {"id": "rna_mcq_28", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "逆转录酶的发现者是？", "o": ["A. Watson和Crick", "B. Temin和Baltimore(1970年)", "C. Meselson和Stahl", "D. Krebs"], "a": "B", "e": "1970年Temin和Baltimore分别发现逆转录酶，1975年诺贝尔奖。", "kp": "rna_s2_6"}, {"id": "rna_mcq_29", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "逆转录酶兼有哪三种酶活力？", "o": ["A. 只有聚合酶", "B. RNA指导的DNA聚合酶+DNA指导的DNA聚合酶+核糖核酸酶H", "C. 连接酶+聚合酶+外切酶", "D. 解旋酶+聚合酶+连接酶"], "a": "B", "e": "逆转录酶三种活力：RNA→DNA、DNA→DNA、核糖核酸酶H(水解RNA-DNA杂交体的RNA)。", "kp": "rna_s2_6"}], "judge": [], "fill": [{"id": "rna_fill_7", "modI": 2, "q": "真核mRNA前体(hnRNA)加工包括:5'端________、3'端________、________(去除内含子)和甲基化。", "a": "加帽(m7G),加polyA尾,拼接", "kp": "rna_s2_0"}, {"id": "rna_fill_8", "modI": 2, "q": "真核mRNA内含子5'端为________,3'端为________(GU-AG规则);分支点保守序列是________。", "a": "GU,AG,UACUAAC", "kp": "rna_s2_4"}, {"id": "rna_fill_9", "modI": 2, "q": "RNase P由________和________组成,其________单独具有催化活性,是________(核酶)。", "a": "蛋白质,RNA(M1RNA),RNA,核酶(ribozyme)", "kp": "rna_s2_10"}], "short": [{"id": "rna_short_4", "modI": 2, "q": "简述真核生物mRNA前体的加工(加帽、加尾、拼接)。", "a": "真核mRNA前体(hnRNA)需三项主要加工:\u000b\u000b【5'端加帽】\u000b①磷酸酶切去5'端磷酸\u000b②鸟苷酰转移酶加鸟苷酸→5'-5'三磷酸连接\u000b③甲基转移酶(S-腺苷Met)甲基化鸟嘌呤N7→m7G帽子\u000b帽结构:m7G5'ppp5'NmpNp-(Cap0/CapI/CapII)\u000b功能:保护5'端、促进翻译起始、剪接\u000b\u000b【3'端加尾】\u000b加尾信号AAUAAA→内切酶在其3'端11-30nt切断→PolyA聚合酶加20~200个A\u000b组蛋白mRNA无polyA尾\u000b\u000b【拼接】\u000b去除内含子、连接外显子\u000bGU-AG规则、分支点UACUAAC\u000b由拼接体(U1/U2/U4/U5/U6 snRNP+蛋白)催化两次转酯反应\u000b\u000b【意义】\u000b成熟mRNA才能被翻译，加工增加了基因产物多样性(选择性拼接)", "kp": "rna_s2_0"}, {"id": "rna_short_5", "modI": 2, "q": "简述RNA拼接(拼接体拼接)的分子机制。", "a": "真核mRNA前体拼接体拼接机制(两次转酯反应):\u000b\u000b【拼接体装配】\u000b①U1 snRNP结合5'拼接点\u000b②U2 snRNP结合分支点(UACUAAC)\u000b③U4/U6+U5 snRNP三聚体进入\u000b\u000b【第一次转酯反应】\u000b①U1、U4释放\u000b②U6结合5'拼接点，U6与U2结合\u000b③分支点未配对A的2'-OH亲核攻击5'拼接点磷酸二酯键\u000b④5'拼接点断开，形成套索结构，释放5'外显子3'-OH\u000b\u000b【第二次转酯反应】\u000b①U5使5'和3'外显子靠近\u000b②5'外显子3'-OH攻击3'拼接点磷酸二酯键\u000b③3'拼接点断开，外显子连接，内含子以套索形式释放\u000b\u000b【关键】\u000b①GU-AG规则(内含子5'GU、3'AG)\u000b②分支点A的2'-OH是关键\u000b③两次转酯反应无ATP消耗\u000b④snRNP起催化作用", "kp": "rna_s2_4"}, {"id": "rna_short_8", "modI": 2, "q": "简述原核生物和真核生物rRNA及tRNA前体的加工。", "a": "【rRNA前体加工】\u000b原核(E.coli):\u000b①7个rRNA转录单位(16S/23S/5S+tRNA基因)\u000b②加工:甲基化(2'-OH,约30个)+切割(RNaseⅢ)+修剪(RNase P/E)\u000b\u000b真核:\u000b①rRNA基因多拷贝(几十~几千)，成簇排列\u000b②16-18S/5.8S/26-28S组成一个转录单位\u000b③甲基化程度更高(>100个)\u000b④甲基化、假尿苷化、切割由snoRNA(核仁小RNA)指导\u000b\u000b【tRNA前体加工】\u000b①核酸内切酶两端切断(RNase P切5'端、RNase F切3'端)\u000b②核酸外切酶(RNase D)3'端修剪\u000b③3'端添加CCAOH(tRNA核苷酰转移酶)\u000b④核苷酸修饰和异构化(假尿苷、甲基化等)\u000b⑤剪接去除内含子(某些真核)\u000b\u000b【关键】\u000bRNase P的RNA(M1RNA)具催化活性→核酶\u000b真核tRNA的3'端CCA是后加的", "kp": "rna_s2_0"}], "calc": [{"id": "rna_calc_1", "modI": 2, "q": "分析真核生物mRNA前体拼接的两次转酯反应,说明为何拼接不需消耗ATP。", "a": "两次转酯反应断裂一个磷酸二酯键同时形成一个新键,能量守恒不需ATP", "steps": "【第一次转酯反应】\u000b分支点A的2'-OH亲核攻击5'拼接点的磷酸二酯键:\u000b• 断裂:5'外显子与内含子之间的磷酸二酯键\u000b• 形成:分支点A与新5'端之间新的2'-5'磷酸二酯键(套索)\u000b• 能量:断裂键释放的能量恰好用于形成新键\u000b\u000b【第二次转酯反应】\u000b5'外显子3'-OH攻击3'拼接点磷酸二酯键:\u000b• 断裂:3'拼接点(内含子与3'外显子之间)磷酸二酯键\u000b• 形成:5'外显子与3'外显子之间磷酸二酯键(外显子连接)\u000b• 释放:内含子以套索形式释放\u000b\u000b【为何不需ATP】\u000b转酯反应=磷酸二酯键的转移(断裂一个+形成一个):\u000b①断裂磷酸二酯键释放的键能与形成新键所需键能相当\u000b②反应前后磷酸二酯键数目不变(2个→2个)\u000b③无需额外的能量输入(与需ATP的DNA连接酶不同)\u000b\u000b【对比】\u000bDNA连接酶需ATP/NAD+(因要把游离的5'-P和3'-OH连接起来需活化)\u000b拼接是转酯反应(键的转移),不需额外活化", "kp": "rna_s2_0"}], "term": [{"id": "rna_term_11", "modI": 2, "term": "前起始复合物(PIC)", "def": "①真核生物转录起始时，RNA聚合酶与通用转录因子在启动子处装配成的复合物（定义）。②真核RNA聚合酶不能识别启动子，必须与通用转录因子装配成PIC才能起始（必要性）。③以Ⅱ类启动子为例，至少涉及6种通用转录因子(TFⅡD/A/B/F/E/H)（组成）。", "kps": "①定义(2分)②必要性(1分)③6种通用因子(2分)", "kp": "rna_s2_2"}, {"id": "rna_term_13", "modI": 2, "term": "hnRNA(核内不均一RNA)", "def": "①真核生物mRNA的前体，因分子大小不均一而得名（定义）。②在核内合成，是RNA聚合酶Ⅱ的转录产物（来源）。③需经加帽、加尾、拼接等加工才成为成熟mRNA（加工）。", "kps": "①定义(2分)②来源(1分)③加工(2分)", "kp": "rna_s2_0"}, {"id": "rna_term_14", "modI": 2, "term": "5'帽结构(5' Cap)", "def": "①真核mRNA 5'端的特殊结构m7G5'ppp5'NmpNp-（定义）。②由磷酸酶、鸟苷酰转移酶、甲基转移酶催化(需S-腺苷Met)（合成）。③分Cap0/CapI/CapII三型（类型）。④功能：保护mRNA 5'端免遭降解、促进翻译起始、参与剪接（功能）。", "kps": "①定义(2分)②合成酶(1分)③类型(1分)④功能(1分)", "kp": "rna_s2_9"}, {"id": "rna_term_15", "modI": 2, "term": "polyA尾(Poly(A) Tail)", "def": "①真核mRNA 3'端的多聚腺苷酸尾巴(20~200个A)（定义）。②在加尾信号AAUAAA的3'端11~30nt处切断，由PolyA聚合酶添加（合成）。③功能：保护mRNA 3'端、促进mRNA出核和翻译（功能）。④组蛋白mRNA等无polyA尾（例外）。", "kps": "①定义(2分)②加尾信号(1分)③功能(1分)④组蛋白例外(1分)", "kp": "rna_s2_2"}, {"id": "rna_term_16", "modI": 2, "term": "RNA拼接(Splicing)", "def": "①真核生物断裂基因转录物加工中，去除内含子、使外显子成为连续序列的过程（定义）。②四种方式：类型I自我拼接、类型II自我拼接、真核mRNA拼接体拼接、核tRNA酶促拼接（方式）。③真核mRNA拼接遵循GU-AG规则，由拼接体催化两次转酯反应（机制）。", "kps": "①定义(2分)②四种方式(1分)③GU-AG规则(1分)④转酯反应(1分)", "kp": "rna_s2_3"}, {"id": "rna_term_17", "modI": 2, "term": "GU-AG规则", "def": "①真核生物mRNA前体的内含子5'端为GU、3'端为AG的拼接规则（定义）。②是真核mRNA内含子两端的高度保守序列（特点）。③作为拼接体识别拼接位点的信号（功能）。", "kps": "①定义(2分)②保守性(2分)③识别信号(1分)", "kp": "rna_s2_4"}, {"id": "rna_term_18", "modI": 2, "term": "拼接体(Spliceosome)", "def": "①真核mRNA前体拼接时，由U1/U2/U4/U5/U6 snRNP和约50种蛋白质组成的复合物（定义）。②snRNP由snRNA(富含U)+蛋白质组成（组成）。③催化两次转酯反应完成内含子切除和外显子连接（功能）。", "kps": "①定义(2分)②snRNP组成(1分)③两次转酯反应(2分)", "kp": "rna_s2_5"}, {"id": "rna_term_19", "modI": 2, "term": "选择性拼接(Alternative Splicing)", "def": "①一个基因的转录产物在不同细胞/发育阶段/生理状态下，通过不同拼接方式得到不同mRNA和翻译产物的现象（定义）。②例：鼠降钙素mRNA前体两个polyA位点，甲状腺产降钙素、脑产降钙素基因相关肽（实例）。③意义：增加基因产物多样性、基因表达调节、进化（意义）。", "kps": "①定义(2分)②实例(1分)③意义(2分)", "kp": "rna_s2_7"}, {"id": "rna_term_20", "modI": 2, "term": "核酶(Ribozyme)", "def": "①具有催化功能的RNA分子（定义）。②例：RNase P的RNA(M1RNA)单独具切割活性；四膜虫rRNA前体自我拼接(L19RNA)（实例）。③发现意义：推翻酶都是蛋白质的传统观念，支持RNA世界假说（意义）。", "kps": "①定义(2分)②实例(2分)③意义(1分)", "kp": "rna_s2_10"}, {"id": "rna_term_21", "modI": 2, "term": "RNase P", "def": "①催化tRNA前体5'端成熟的核酸内切酶（定义）。②由蛋白质和RNA(M1RNA)组成（组成）。③原核RNase P的RNA(375nt)单独具切割活性→核酶（催化本质）。", "kps": "①定义(2分)②蛋白+RNA组成(1分)③RNA具催化活性(2分)", "kp": "rna_s2_0"}, {"id": "rna_term_27", "modI": 2, "term": "前病毒(Provirus)", "def": "①逆转录病毒cDNA在整合酶作用下整合入宿主染色体后的DNA形式（定义）。②随宿主细胞DNA复制和转录（特点）。③是逆转录病毒潜伏感染和致癌的分子基础（意义）。④Temin前病毒学说(1964)提出（来源）。", "kps": "①定义(2分)②随宿主复制(1分)③意义(1分)④前病毒学说(1分)", "kp": null}]}, {"i": 3, "name": "模块四：RNA复制/RNAi/逆转录", "slides": [{"i": 0, "sec": "RNA的生物合成和转录后加工", "title": "RNAi诺贝尔奖 (p71-p72) (p1)", "notes": "2006年诺贝尔生理学或医学奖授予Andrew Fire和Craig Mello，奖励RNAi(双链RNA引发的基因沉默)机制的发现。\u000b5.RNA在生物进化中的作用：RNA拼接和编辑增加遗传信息多样性、消除突变危害、促进进化。", "page": 1, "level": "掌握", "img": "assets/img/rna/p001.jpg", "anim": null, "fig": "", "points": ["①2006年诺奖授予Fire和Mello", "②奖励发现RNAi（双链RNA引发基因沉默）", "③RNA拼接和编辑增加多样性、消除突变、促进进化"], "check": null, "cards": null}, {"i": 1, "sec": "RNA的生物合成和转录后加工", "title": "第三节 RNA的复制 (p73-p74) (p2)", "notes": "第三节 RNA的复制——RNA指导下RNA的合成。\u000bRNA复制酶：以RNA为模板，以4种NTP为底物，聚合方向5'→3'。\u000b内容：噬菌体QβRNA复制、病毒RNA复制方式、SARS/新冠病毒。", "page": 2, "level": "掌握", "img": "assets/img/rna/p002.jpg", "anim": null, "fig": "", "points": ["①RNA复制：RNA指导下合成RNA", "②RNA复制酶以RNA为模板、4种NTP为底物", "③聚合方向5'→3'；涉及Qβ噬菌体、病毒、新冠"], "check": null, "cards": null}, {"i": 2, "sec": "RNA的生物合成和转录后加工", "title": "噬菌体QβRNA复制 (p75-p76) (p3)", "notes": "一、噬菌体QβRNA的复制。\u000bQβ是直径20nm正二十面体小噬菌体，1条RNA单链(+链)4500核苷酸。\u000b复制酶4个亚基：β亚基(催化中心,病毒编码)、α(核糖体蛋白S1)、γ(EF-Tu)、δ(EF-Ts)(宿主细胞提供)。\u000b复制：+RNA→-中间体→释放-RNA→-+中间体→+RNA。", "page": 3, "level": "掌握", "img": "assets/img/rna/p003.jpg", "anim": null, "fig": "", "points": ["①Qβ为+ssRNA小噬菌体，4500nt，正二十面体", "②复制酶4亚基：β催化(病毒编码)，αγδ由宿主提供", "③α=S1，γ=EF-Tu，δ=EF-Ts", "④复制经-RNA中间体，滚环式合成+RNA"], "check": null, "cards": null}, {"i": 3, "sec": "RNA的生物合成和转录后加工", "title": "病毒RNA复制方式 (p77-p78) (p4)", "notes": "二、病毒RNA复制主要方式。\u000b1.RNA直接作模板(RNA→RNA)：+RNA(Qβ、脊髓灰质炎病毒、SARS、新冠)、-RNA(狂犬病病毒)、±RNA(呼肠孤病毒)、++逆转录病毒。\u000b2.RNA→DNA→RNA(逆转录作用)。\u000b不对称复制。", "page": 4, "level": "掌握", "img": "assets/img/rna/p004.jpg", "anim": null, "fig": "", "points": ["①RNA直接作模板：+RNA、-RNA、±RNA、++逆转录病毒", "②RNA→DNA→RNA为逆转录途径", "③复制均不对称，先合成互补链", "④+RNA病毒mRNA可直接翻译"], "check": null, "cards": null}, {"i": 4, "sec": "RNA的生物合成和转录后加工", "title": "SARS病毒 (p79-p80) (p5)", "notes": "SARS(严重急性呼吸综合征)病毒：单链(+)RNA，RNA 29724核苷酸，5'端甲基化帽子、3'端polyA尾，与真核mRNA相似。\u000b含刺突糖蛋白S、小包膜糖蛋白E、膜糖蛋白M、核衣壳蛋白。\u000bRNA间重组率高→病毒易变异。", "page": 5, "level": "掌握", "img": "assets/img/rna/p005.jpg", "anim": null, "fig": "", "points": ["①SARS为单链(+)RNA，29724nt", "②5'帽子、3'polyA，似真核mRNA", "③结构蛋白S、E、M、N", "④RNA重组率高，病毒易变异"], "check": null, "cards": null}, {"i": 5, "sec": "RNA的生物合成和转录后加工", "title": "新型冠状病毒 (p81-p83) (p6)", "notes": "新冠病毒(2019-nCoV/SARS-CoV-2)：β属冠状病毒，直径60-140nm，与SARS-CoV相似性79.5%。\u000b基因组1条正链RNA(+ssRNA)29891核苷酸，编码9860氨基酸。\u000b结构蛋白：S刺突蛋白、E包膜、M膜、N核衣壳。\u000b非结构蛋白Nsp1-16(Nsp12=RdRp RNA依赖RNA聚合酶、Nsp13解旋酶)。\u000b感染：S蛋白结合ACE2受体→膜融合→释放RNA→复制组装出芽。", "page": 6, "level": "掌握", "img": "assets/img/rna/p006.jpg", "anim": null, "fig": "", "points": ["①SARS-CoV-2为β属冠状病毒，+ssRNA 29891nt", "②与SARS相似性79.5%，编码9860aa", "③结构蛋白S/E/M/N；Nsp12=RdRp，Nsp13解旋酶", "④S结合ACE2→膜融合→释放RNA→复制出芽"], "check": null, "cards": null}, {"i": 6, "sec": "RNA的生物合成和转录后加工", "title": "第四节 逆转录作用 (p84-p85) (p7)", "notes": "第四节 逆转录作用——RNA指导下的DNA合成。\u000b逆转录(reverse transcription)：以RNA为模板，按RNA中的核苷酸顺序合成DNA的过程。", "page": 7, "level": "掌握", "img": "assets/img/rna/p007.jpg", "anim": null, "fig": "", "points": ["①逆转录：以RNA为模板合成DNA", "②又称RNA指导的DNA合成", "③中心法则的补充，RNA→DNA", "④产物为cDNA，可整合入基因组"], "check": null, "cards": null}, {"i": 7, "sec": "RNA的生物合成和转录后加工", "title": "逆转录酶的发现 (p86-p87) (p8)", "notes": "一、逆转录酶(reverse transcriptase)的发现。\u000b1964年Temin提出前病毒学说(致癌RNA病毒感染中存在DNA中间体)。\u000b1970年Temin和Baltimore分别从致癌RNA病毒中发现逆转录酶。\u000b1975年获诺贝尔生理或医学奖。\u000b杜尔贝科证明DNA病毒可嵌入基因组。", "page": 8, "level": "掌握", "img": "assets/img/rna/p008.jpg", "anim": null, "fig": "", "points": ["①1964 Temin提出前病毒学说", "②1970 Temin与Baltimore发现逆转录酶", "③1975年获诺贝尔生理或医学奖", "④杜尔贝科证明DNA可嵌入基因组"], "check": null, "cards": null}, {"i": 8, "sec": "RNA的生物合成和转录后加工", "title": "逆转录酶的性质 (p88)", "notes": "二、逆转录酶的性质：兼有三种酶活力——①RNA指导的DNA聚合酶；\u000b②DNA指导的DNA聚合酶；\u000b③核糖核酸酶H(水解RNA-DNA杂交分子中的RNA)。\u000b需4种dNTP、模板和引物(tRNA)、Mg2+和还原剂，聚合方向5'→3'。", "page": 88, "level": "掌握", "img": "assets/img/rna/p088.jpg", "anim": null, "fig": "", "points": ["①兼有三种酶活：RDDP、DDDP、RNase H", "②RNase H水解RNA-DNA杂交中的RNA", "③需dNTP、模板、tRNA引物、Mg2+", "④聚合方向5'→3'"], "check": null, "cards": null}, {"i": 9, "sec": "RNA的生物合成和转录后加工", "title": "逆转录病毒基因组 (p89-p90) (p10)", "notes": "三、逆转录病毒基因组：两条相同(+)RNA链在5'端区以氢键结合。\u000b两端相同正向重复序列(R)，5'端帽子、3'端polyA，5'端1分子宿主tRNA作逆转录引物。\u000b典型基因组7000-10000核苷酸，3个基因：gag(核心蛋白)、pol(蛋白酶/整合酶/逆转录酶)、env(包膜糖蛋白)。\u000b有些含癌基因(如人类嗜T细胞病毒)。", "page": 10, "level": "掌握", "img": "assets/img/rna/p010.jpg", "anim": null, "fig": "", "points": ["①基因组为两条相同(+)RNA，5'端氢键相连", "②两端有R重复序列，5'帽子、3'polyA", "③宿主tRNA作逆转录引物，7000-10000nt", "④三基因gag、pol、env，部分含癌基因"], "check": null, "cards": null}, {"i": 10, "sec": "RNA的生物合成和转录后加工", "title": "逆转录过程 (p91-p92) (p11)", "notes": "四、逆转录过程：病毒RNA侵染宿主→RNA指导的DNA聚合酶以tRNA为引物合成DNA→RNA-cDNA杂交分子→核糖核酸酶H水解RNA→DNA指导的DNA聚合酶合成双链DNA→整合入染色体(前病毒)→随宿主复制转录。", "page": 11, "level": "掌握", "img": "assets/img/rna/p011.jpg", "anim": null, "fig": "图示逆转录全过程：从病毒RNA出发，经杂交分子、双链DNA，最终整合入宿主染色体，注意各酶（逆转录酶、RNase H）的作用顺序。", "points": ["①病毒RNA进入宿主，逆转录酶以tRNA为引物合成DNA", "②形成RNA-cDNA杂交分子，RNase H水解RNA链", "③DNA聚合酶合成双链DNA，整合为前病毒", "④前病毒随宿主染色体复制转录，完成逆转录周期"], "check": null, "cards": null}, {"i": 11, "sec": "RNA的生物合成和转录后加工", "title": "逆转录的生物学意义 (p93)", "notes": "五、逆转录的生物学意义：①逆转录酶是研究DNA-RNA关系、DNA克隆的重要工具酶(获得cDNA、反推RNA顺序)；\u000b②有助于了解RNA病毒致癌机理；\u000b③揭示HIV等病毒致病机理提供防治策略；\u000b④逆转录病毒可作信息载体参与基因治疗。", "page": 93, "level": "掌握", "img": "assets/img/rna/p093.jpg", "anim": null, "fig": "", "points": ["①逆转录酶是DNA克隆、cDNA合成的重要工具酶", "②有助于阐明RNA病毒致癌机理", "③揭示HIV等致病机理，提供防治策略", "④逆转录病毒可作载体用于基因治疗"], "check": null, "cards": null}], "mcq": [{"id": "rna_mcq_30", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "逆转录病毒的典型基因是？", "o": ["A. gag/pol/env", "B. lacZ", "C. 只有env", "D. 无基因"], "a": "A", "e": "逆转录病毒3基因：gag(核心蛋白)、pol(蛋白酶/整合酶/逆转录酶)、env(包膜糖蛋白)。", "kp": "rna_s3_9"}, {"id": "rna_mcq_31", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "逆转录病毒整合入宿主染色体后的DNA称？", "o": ["A. 质粒", "B. 前病毒(provirus)", "C. 转座子", "D. 端粒"], "a": "B", "e": "逆转录病毒cDNA在整合酶作用下整合入宿主染色体→前病毒，随宿主复制转录。", "kp": "rna_s3_9"}, {"id": "rna_mcq_32", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "转录泡(transcription bubble)是什么？", "o": ["A. 复制泡", "B. 转录时DNA双链局部解开的区域", "C. 启动子", "D. 终止子"], "a": "B", "e": "转录泡=转录时RNA聚合酶处DNA局部解开形成的解链区。", "kp": "rna_s3_6"}, {"id": "rna_mcq_33", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "原核生物rRNA前体加工的主要酶？", "o": ["A. RNaseⅢ/Rnase P/Rnase E", "B. 拼接体", "C. 逆转录酶", "D. PolyA聚合酶"], "a": "A", "e": "原核rRNA加工：甲基化+切割(RNaseⅢ)+修剪(RNase P/E)。", "kp": "rna_s3_0"}, {"id": "rna_mcq_34", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "真核rRNA前体加工由什么RNA指导？", "o": ["A. snRNA", "B. snoRNA(核仁小RNA)", "C. miRNA", "D. tRNA"], "a": "B", "e": "真核rRNA甲基化、假尿苷化、切割由核仁小RNA(snoRNA)指导。", "kp": "rna_s3_1"}, {"id": "rna_mcq_35", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "tRNA前体3'端CCAOH由什么酶添加？", "o": ["A. RNase P", "B. tRNA核苷酰转移酶", "C. PolyA聚合酶", "D. 逆转录酶"], "a": "B", "e": "tRNA核苷酰转移酶在3'端添加CCAOH。真核tRNA的CCA是后加的。", "kp": "rna_s3_0"}, {"id": "rna_mcq_36", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "类型I自我拼接需要什么介导？", "o": ["A. 蛋白质", "B. 鸟苷(鸟苷酸)", "C. 套索", "D. ATP"], "a": "B", "e": "类型I自我拼接由鸟苷(鸟苷酸)的3'-OH介导转酯反应。类型II形成套索。", "kp": "rna_s3_0"}, {"id": "rna_mcq_37", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "新冠病毒的基因组是？", "o": ["A. 双链DNA", "B. 单链正链RNA(+ssRNA,约29900nt)", "C. 单链负链RNA", "D. 双链RNA"], "a": "B", "e": "SARS-CoV-2基因组为1条正链RNA(+ssRNA)29891核苷酸，编码S/E/M/N和Nsp1-16。", "kp": "rna_s3_9"}, {"id": "rna_mcq_38", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "新冠病毒进入宿主细胞结合的受体是？", "o": ["A. CD4", "B. ACE2(血管紧张素转化酶2)", "C. CCR5", "D. 胰岛素受体"], "a": "B", "e": "SARS-CoV-2的S刺突蛋白与宿主细胞表面ACE2受体结合→膜融合→进入细胞。", "kp": "rna_s3_5"}], "judge": [], "fill": [{"id": "rna_fill_10", "modI": 3, "q": "逆转录是以________为模板合成DNA,催化酶是________,它兼有________、________和________三种酶活力。", "a": "RNA,逆转录酶,RNA指导的DNA聚合酶,DNA指导的DNA聚合酶,核糖核酸酶H", "kp": "rna_s3_8"}, {"id": "rna_fill_11", "modI": 3, "q": "逆转录病毒典型三个基因是________(核心蛋白)、________(蛋白酶/整合酶/逆转录酶)、________(包膜糖蛋白)。", "a": "gag,pol,env", "kp": "rna_s3_9"}, {"id": "rna_fill_12", "modI": 3, "q": "RNAi中,siRNA/miRNA与________复合物结合,降解靶mRNA;2006年诺贝尔奖授予________和________。", "a": "RISC(RNA诱导沉默复合物),Fire,Mello", "kp": "rna_s3_0"}], "short": [{"id": "rna_short_6", "modI": 3, "q": "简述逆转录酶的性质、逆转录过程及生物学意义。", "a": "【逆转录酶性质】\u000b兼三种酶活力:\u000b①RNA指导的DNA聚合酶(RNA→DNA)\u000b②DNA指导的DNA聚合酶(DNA→DNA)\u000b③核糖核酸酶H(水解RNA-DNA杂交体的RNA)\u000b需dNTP、模板和引物(tRNA)、Mg2+和还原剂，方向5'→3'\u000b\u000b【逆转录过程】\u000b①病毒RNA侵染宿主\u000b②以tRNA为引物，RNA指导DNA聚合酶合成DNA\u000b③形成RNA-cDNA杂交分子\u000b④核糖核酸酶H水解RNA\u000b⑤DNA指导DNA聚合酶合成双链DNA\u000b⑥整合酶使双链DNA整合入宿主染色体→前病毒\u000b⑦前病毒随宿主复制转录\u000b\u000b【生物学意义】\u000b①逆转录酶是研究DNA-RNA关系、DNA克隆的重要工具酶(cDNA合成、反推RNA顺序)\u000b②了解RNA病毒致癌机理\u000b③揭示HIV致病机理提供防治策略\u000b④逆转录病毒可作基因治疗载体", "kp": "rna_s3_11"}, {"id": "rna_short_7", "modI": 3, "q": "简述RNA干扰(RNAi)的机制和生物学意义。", "a": "【RNAi定义】\u000b由双链RNA(dsRNA)引发的特异性基因沉默现象。\u000b\u000b【机制】\u000b①dsRNA(内源miRNA前体或外源长dsRNA)被RNA内切酶(Dicer)切成小片段\u000b②siRNA(~23nt)或miRNA(70-90nt前体加工而来)\u000b③siRNA/miRNA与RISC(RNA诱导沉默复合物)结合\u000b④RISC中Argonaute(Ago)蛋白具内切酶活性\u000b⑤siRNA引导RISC识别互补的靶mRNA→降解靶mRNA\u000b⑥miRNA不完全互补→抑制翻译\u000b\u000b【基因沉默类型】\u000b①转录前水平:DNA修饰/异染色质化\u000b②转录后水平:靶mRNA降解或抑制翻译\u000b\u000b【生物学意义】\u000b①基因表达调控的重要机制\u000b②抵抗病毒侵染、转座子\u000b③研究基因功能的工具(基因敲低)\u000b④疾病治疗(基因治疗)、农业应用\u000b\u000b【里程碑】\u000b2006年诺贝尔奖授予Fire和Mello", "kp": "rna_s3_11"}, {"id": "rna_short_9", "modI": 3, "q": "简述RNA的编辑及其生物学意义。", "a": "【RNA编辑定义】\u000b改变RNA的编码序列(转录后修饰编码信息)。\u000b\u000b【编辑类型】\u000b①U的插入与删除(guide RNA指导)——锥虫线粒体mRNA\u000b②C、A或U的插入\u000b③C→U转变\u000b\u000b【实例】\u000b①锥虫线粒体细胞色素氧化酶亚基II mRNA：移码位点附近插入4个额外U(20S复合体:核酸内切酶+末端尿苷酰转移酶+RNA连接酶)\u000b②载脂蛋白apoB-100基因:C→U使CAA(谷氨酰胺)→UAA(终止密码)→小肠产生apoB-48(肝产生apoB-100)\u000b\u000b【生物学意义】\u000b①消除移码突变的危害\u000b②增加基因产物的多样性\u000b③使基因产物获得新的结构和功能\u000b④是基因调控的重要方式\u000b⑤促进生物进化", "kp": "rna_s3_11"}], "calc": [{"id": "rna_calc_3", "modI": 3, "q": "论述RNA生物功能的多样性(RNA世界假说的证据)。", "a": "RNA既能存储遗传信息又能催化反应,是生命起源RNA世界假说的核心", "steps": "【RNA的多种功能】\u000b①遗传信息载体和翻译中介:mRNA携带密码、rRNA组成核糖体、tRNA转运氨基酸\u000b②催化功能(核酶):RNase P的M1RNA具催化活性、四膜虫rRNA自我拼接、核糖体肽键形成由23S rRNA催化\u000b③转录后加工:snoRNA参与rRNA加工、snRNA参与hnRNA拼接、端粒酶RNA作模板\u000b④基因表达调控:miRNA/siRNA参与RNAi、反义RNA、核开关\u000b⑤其他:引导RNA参与RNA编辑\u000b\u000b【RNA世界假说的证据】\u000b①RNA兼具信息存储(DNA功能)和催化(蛋白质功能)\u000b②rRNA催化肽键形成→核糖体本质是核酶\u000b③RNA可以自我复制(RNA复制酶)\u000b④RNA可逆转录为DNA\u000b\u000b【结论】\u000bRNA的多功能性支持生命起源早期可能是RNA世界\u000b→RNA先出现,既能催化又能存储信息\u000b→后来DNA(更稳定)接管信息存储,蛋白质(更多样)接管催化\u000b→RNA保留中间角色(遗传信息流动的桥梁)", "kp": "rna_s3_0"}, {"id": "rna_calc_4", "modI": 3, "q": "论述逆转录病毒的致病机理及逆转录在分子生物学中的应用。", "a": "逆转录病毒通过前病毒形式整合宿主基因组致病,逆转录酶是分子克隆核心工具酶", "steps": "【逆转录病毒致病机理】\u000b①病毒颗粒(表面蛋白+跨膜蛋白)与宿主细胞融合\u000b②RNA在细胞质逆转录为cDNA\u000b③整合酶使cDNA整合入宿主染色体→前病毒\u000b④前病毒随宿主DNA复制转录→产生新病毒或癌变\u000b\u000b【致癌机理】\u000b①前病毒插入宿主基因组→插入突变激活原癌基因\u000b②病毒携带癌基因(如人类嗜T细胞病毒癌基因编码酪氨酸蛋白激酶,高表达致细胞分裂失控)\u000b③前病毒启动子驱动邻近基因过度表达\u000b\u000b【HIV致病机理】\u000b①HIV是逆转录病毒,感染CD4+T细胞\u000b②逆转录酶易错(无校对)→高突变率→逃避免疫和耐药\u000b③整合入基因组潜伏→慢性感染\u000b④破坏免疫系统→艾滋病\u000b\u000b【逆转录的应用】\u000b①cDNA合成:逆转录酶以mRNA为模板合成cDNA→构建cDNA文库\u000b②RT-PCR:检测基因表达、诊断病毒\u000b③反推RNA顺序\u000b④基因治疗:逆转录病毒作载体导入治疗基因\u000b\u000b【关键】\u000b逆转录酶无校对→高突变率→既是病毒进化和耐药的原因,也是分子克隆中引入错误的问题", "kp": "rna_s3_11"}, {"id": "rna_calc_5", "modI": 3, "q": "分析新冠病毒(SARS-CoV-2)的结构、基因组和感染复制过程。", "a": "SARS-CoV-2是正链RNA病毒,S蛋白结合ACE2受体入侵,RNA复制+翻译组装出芽", "steps": "【病毒结构】\u000b①刺突蛋白S(结合受体)\u000b②包膜蛋白E\u000b③膜蛋白M\u000b④核衣壳蛋白N\u000b\u000b【基因组】\u000b①1条正链RNA(+ssRNA),29891核苷酸\u000b②编码9860氨基酸\u000b③结构蛋白4个(S/E/M/N)\u000b④非结构蛋白16个(Nsp1-16)\u000b\u000b【关键非结构蛋白】\u000bNsp1:参与RNA加工\u000bNsp3/Nsp5:蛋白酶(多肽链加工)\u000bNsp12:RNA依赖RNA聚合酶(RdRp)\u000bNsp13:解旋酶\u000b\u000b【感染复制过程】\u000b①吸附:S蛋白与宿主细胞ACE2受体结合\u000b②侵入:跨膜丝氨酸蛋白酶2(TMPRSS2)激活,膜融合\u000b③释放:遗传物质RNA释放入胞质\u000b④翻译:以基因组RNA为模板翻译多聚蛋白pp1a/b\u000b⑤蛋白水解:水解成16个非结构蛋白\u000b⑥转录复制:形成RNA聚合酶复合物,转录复制基因组\u000b⑦翻译结构蛋白:S/M/E在内质网翻译,N在核糖体翻译\u000b⑧组装:S/M/E/N组装病毒颗粒\u000b⑨出芽释放\u000b\u000b【抗病毒靶点】\u000bRdRp(瑞德西韦靶点)、蛋白酶(帕罗维德靶点)、S蛋白(疫苗靶点)", "kp": "rna_s3_5"}], "term": [{"id": "rna_term_22", "modI": 3, "term": "RNA编辑(RNA Editing)", "def": "①改变RNA编码序列的转录后修饰过程（定义）。②类型：U的插入与删除(guide RNA指导)、C/A/U插入、C→U等（类型）。③例：锥虫线粒体mRNA插入U、apoB mRNA C→U产生终止密码（实例）。④意义：消除移码突变危害、增加基因产物多样性、基因调控（意义）。", "kps": "①定义(2分)②类型(1分)③实例(1分)④意义(1分)", "kp": "rna_s3_0"}, {"id": "rna_term_23", "modI": 3, "term": "RNAi(RNA干扰)", "def": "①由双链RNA引发的特异性基因沉默现象（定义）。②机制：dsRNA被RNA内切酶(Dicer)切成siRNA(~23nt)/miRNA→与RISC结合→降解靶mRNA或抑制翻译（机制）。③基因沉默含转录前水平(DNA修饰/异染色质化)和转录后水平(mRNA降解/翻译抑制)（类型）。④2006年诺贝尔奖(Fire和Mello)（里程碑）。", "kps": "①定义(2分)②机制(2分)③类型(1分)④诺贝尔奖(1分)", "kp": "rna_s3_0"}]}], "mcq": [{"id": "rna_mcq_1", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "转录(transcription)的定义是什么？", "o": ["A. DNA→蛋白质", "B. DNA指导下RNA的合成", "C. RNA→DNA", "D. RNA→蛋白质"], "a": "B", "e": "转录=DNA指导下RNA的合成。逆转录=RNA指导下DNA合成。翻译=RNA指导蛋白质合成。", "kp": "rna_s0_6"}, {"id": "rna_mcq_2", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "不对称转录中,与转录出的RNA顺序相同的链是？", "o": ["A. 模板链", "B. 编码链(+链,仅T代替U)", "C. 引物链", "D. 反义链"], "a": "B", "e": "编码链(+链)与RNA顺序相同(T→U)；模板链(-链)为RNA提供转录模板。", "kp": "rna_s0_3"}, {"id": "rna_mcq_3", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "原核生物的转录单位通常是？", "o": ["A. 单顺反子", "B. 多顺反子(多个基因→多种蛋白质)", "C. 无顺反子", "D. 只含rRNA"], "a": "B", "e": "原核为多顺反子(一个转录单位含多个基因)；真核为单顺反子(一个基因)。", "kp": "rna_s0_5"}, {"id": "rna_mcq_4", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "启动子(promoter)的定义是什么？", "o": ["A. 终止信号", "B. RNA聚合酶识别、结合和开始转录的DNA序列", "C. 翻译起点", "D. 复制起点"], "a": "B", "e": "启动子是RNA聚合酶识别结合起始转录的DNA序列。转录因子是起始转录所需的辅助蛋白。", "kp": "rna_s0_6"}, {"id": "rna_mcq_5", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "原核启动子Pribnow box位于什么位置？", "o": ["A. -35区", "B. -10区(TATAAT)", "C. +1区", "D. -75区"], "a": "B", "e": "Pribnow box(TATAAT)在-10区,是双链局部解开区。TTGACA在-35区,提供全酶识别信号。", "kp": "rna_s0_8"}, {"id": "rna_mcq_6", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "真核生物中负责转录mRNA的RNA聚合酶是？", "o": ["A. RNA聚合酶Ⅰ", "B. RNA聚合酶Ⅱ", "C. RNA聚合酶Ⅲ", "D. 三者均可"], "a": "B", "e": "PolⅡ转录mRNA/大多数snRNA(对α-鹅膏蕈碱敏感)；PolⅠ转录rRNA；PolⅢ转录tRNA/5SRNA。", "kp": "rna_s0_0"}, {"id": "rna_mcq_7", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "RNA聚合酶催化链延伸的方向是？", "o": ["A. 3'→5'", "B. 5'→3'", "C. 双向", "D. 随机"], "a": "B", "e": "RNA聚合酶沿5'→3'方向聚合，不需引物，无校对(外切酶)活性。", "kp": "rna_s0_12"}, {"id": "rna_mcq_8", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "原核RNA聚合酶中识别启动子的是哪个亚基？", "o": ["A. α", "B. β", "C. σ因子", "D. ω"], "a": "C", "e": "σ因子(起始亚基)识别启动子促进转录起始。核心酶α2ββ'催化链延长。", "kp": "rna_s0_12"}, {"id": "rna_mcq_9", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "转录起始时,新生RNA链5'端通常是什么？", "o": ["A. pppU", "B. pppA或pppG(第一个核苷酸通常ATP/GTP)", "C. OH", "D. 帽子"], "a": "B", "e": "转录第一个核苷酸通常是ATP或GTP,新生链5'端为pppA或pppG(三磷酸保留)。", "kp": "rna_s0_0"}, {"id": "rna_mcq_10", "mod": "模块一：转录机制(启动子/酶/过程)", "modI": 0, "q": "依赖rho因子的转录终止中,rho蛋白的活性？", "o": ["A. 聚合酶活性", "B. NTP酶活力+RNA-DNA解螺旋酶活力", "C. 连接酶", "D. 甲基化酶"], "a": "B", "e": "rho因子具NTP酶+RNA-DNA解螺旋酶活力，解开RNA-DNA杂交体终止转录。", "kp": "rna_s0_11"}, {"id": "rna_mcq_11", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "α-鹅膏蕈碱(α-amanitin)抑制什么？", "o": ["A. 细菌RNA聚合酶β亚基", "B. 真核RNA聚合酶Ⅱ", "C. DNA聚合酶", "D. 核糖体"], "a": "B", "e": "α-鹅膏蕈碱抑制真核PolⅡ。利福平抑制细菌RNA聚合酶β亚基。", "kp": "rna_s1_7"}, {"id": "rna_mcq_12", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "放线菌素D的转录抑制机制？", "o": ["A. 抑制聚合酶", "B. 插入DNA双链碱基对之间,抑制模板功能", "C. 抑制核苷酸合成", "D. 降解RNA"], "a": "B", "e": "放线菌素D嵌入DNA双链碱基对之间→阻断转录。溴化乙锭也是嵌入染料。", "kp": "rna_s1_7"}, {"id": "rna_mcq_13", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "真核mRNA前体(hnRNA)加工不包括什么？", "o": ["A. 5'端加帽", "B. 3'端加polyA尾", "C. 拼接(去除内含子)", "D. 添加CCAOH末端"], "a": "D", "e": "添加CCAOH是tRNA的加工。hnRNA加工：加帽、加尾、拼接、甲基化。", "kp": "rna_s1_10"}, {"id": "rna_mcq_14", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "真核mRNA的5'帽结构是？", "o": ["A. m7G5'ppp5'NmpNp-", "B. polyA", "C. CCA", "D. 假尿苷"], "a": "A", "e": "帽结构m7G5'ppp5'NmpNp-。polyA是3'尾。CCA是tRNA 3'端。", "kp": "rna_s1_4"}, {"id": "rna_mcq_15", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "polyA尾的加尾信号是什么？", "o": ["A. TATA", "B. AAUAAA", "C. GU", "D. AG"], "a": "B", "e": "加尾信号AAUAAA，在其3'端11~30nt处切断，PolyA聚合酶加20~200个A。组蛋白mRNA无polyA尾。", "kp": "rna_s1_2"}, {"id": "rna_mcq_16", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "真核mRNA内含子的GU-AG规则是什么？", "o": ["A. 内含子5'端GU,3'端AG", "B. 内含子5'端AG,3'端GU", "C. 外显子GU-AG", "D. 启动子GU-AG"], "a": "A", "e": "GU-AG规则：真核mRNA前体内含子5'端GU、3'端AG，是拼接识别的重要保守序列。", "kp": "rna_s1_4"}, {"id": "rna_mcq_17", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "拼接体(spliceosome)主要由什么组成？", "o": ["A. 核糖体", "B. U1/U2/U4/U5/U6 snRNP和约50种蛋白质", "C. 端粒酶", "D. RNA聚合酶"], "a": "B", "e": "拼接体由U1、U2、U4-6 snRNP(含snRNA+蛋白)和约50种蛋白组成。", "kp": "rna_s1_8"}, {"id": "rna_mcq_18", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "RNA拼接中,分支点保守序列是什么？", "o": ["A. TATAAT", "B. UACUAAC", "C. AAUAAA", "D. GU"], "a": "B", "e": "分支点序列UACUAAC十分保守，其中未配对A的2'-OH亲核攻击5'拼接点(第一次转酯反应)。", "kp": "rna_s1_8"}, {"id": "rna_mcq_19", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "选择性拼接(alternative splicing)的含义？", "o": ["A. 基因突变", "B. 一个基因通过不同拼接方式产生不同mRNA和翻译产物", "C. RNA降解", "D. 转录终止"], "a": "B", "e": "选择性拼接使一个基因在不同细胞/发育阶段产生多种mRNA和蛋白，增加基因产物多样性。", "kp": "rna_s1_8"}, {"id": "rna_mcq_20", "mod": "模块二：真核转录与抑制剂", "modI": 1, "q": "RNase P的催化本质是？", "o": ["A. 蛋白质", "B. RNA(M1RNA)具催化活性(核酶)", "C. 多糖", "D. 脂类"], "a": "B", "e": "RNase P由蛋白质+RNA组成，其RNA(M1RNA)单独具切割活性→核酶(ribozyme)。", "kp": "rna_s1_12"}, {"id": "rna_mcq_21", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "RNA编辑(editing)的含义？", "o": ["A. 剪接", "B. 改变RNA的编码序列(U插入/删除,C→U等)", "C. 加帽", "D. 加尾"], "a": "B", "e": "RNA编辑改变编码序列：如锥虫线粒体mRNA插入U、apoB mRNA C→U(终止密码)。", "kp": "rna_s2_8"}, {"id": "rna_mcq_22", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "载脂蛋白apoB-100基因RNA编辑(C→U)的结果？", "o": ["A. 延长蛋白", "B. CAA→UAA终止密码,小肠产生apoB-48", "C. 移码", "D. 无变化"], "a": "B", "e": "C→U使CAA(谷氨酰胺)→UAA(终止密码)，小肠肽链提前终止产生apoB-48。", "kp": "rna_s2_9"}, {"id": "rna_mcq_23", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "RNA干扰(RNAi)中,与siRNA/miRNA结合的复合物是？", "o": ["A. 拼接体", "B. RISC(RNA诱导沉默复合物)", "C. 核糖体", "D. 复制体"], "a": "B", "e": "siRNA/miRNA与RISC结合，指导降解靶mRNA或抑制翻译→基因沉默。", "kp": "rna_s2_11"}, {"id": "rna_mcq_24", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "2006年诺贝尔奖奖励的发现是？", "o": ["A. DNA复制", "B. RNAi(双链RNA引发的基因沉默)", "C. 逆转录酶", "D. 端粒酶"], "a": "B", "e": "2006年诺贝尔生理或医学奖授予Fire和Mello，奖励RNAi机制的发现。", "kp": "rna_s2_2"}, {"id": "rna_mcq_25", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "RNA复制酶(RNA replicase)的特点？", "o": ["A. 需DNA模板", "B. 以RNA为模板,以4种NTP为底物,5'→3'", "C. 需引物", "D. 有校对活性"], "a": "B", "e": "RNA复制酶以RNA为模板合成RNA(RNA→RNA)，5'→3'，不需DNA。", "kp": "rna_s2_3"}, {"id": "rna_mcq_26", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "噬菌体Qβ复制酶的催化亚基是？", "o": ["A. α", "B. β亚基(病毒编码,催化中心)", "C. γ", "D. δ"], "a": "B", "e": "Qβ复制酶β亚基(病毒编码)是催化中心；α(S1)、γ(EF-Tu)、δ(EF-Ts)来自宿主。", "kp": "rna_s2_10"}, {"id": "rna_mcq_27", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "逆转录(reverse transcription)的定义？", "o": ["A. DNA→RNA", "B. 以RNA为模板合成DNA", "C. RNA→RNA", "D. DNA→DNA"], "a": "B", "e": "逆转录=以RNA为模板，按RNA核苷酸顺序合成DNA(RNA指导的DNA合成)。", "kp": "rna_s2_7"}, {"id": "rna_mcq_28", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "逆转录酶的发现者是？", "o": ["A. Watson和Crick", "B. Temin和Baltimore(1970年)", "C. Meselson和Stahl", "D. Krebs"], "a": "B", "e": "1970年Temin和Baltimore分别发现逆转录酶，1975年诺贝尔奖。", "kp": "rna_s2_6"}, {"id": "rna_mcq_29", "mod": "模块三：转录后加工(rRNA/tRNA/mRNA)", "modI": 2, "q": "逆转录酶兼有哪三种酶活力？", "o": ["A. 只有聚合酶", "B. RNA指导的DNA聚合酶+DNA指导的DNA聚合酶+核糖核酸酶H", "C. 连接酶+聚合酶+外切酶", "D. 解旋酶+聚合酶+连接酶"], "a": "B", "e": "逆转录酶三种活力：RNA→DNA、DNA→DNA、核糖核酸酶H(水解RNA-DNA杂交体的RNA)。", "kp": "rna_s2_6"}, {"id": "rna_mcq_30", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "逆转录病毒的典型基因是？", "o": ["A. gag/pol/env", "B. lacZ", "C. 只有env", "D. 无基因"], "a": "A", "e": "逆转录病毒3基因：gag(核心蛋白)、pol(蛋白酶/整合酶/逆转录酶)、env(包膜糖蛋白)。", "kp": "rna_s3_9"}, {"id": "rna_mcq_31", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "逆转录病毒整合入宿主染色体后的DNA称？", "o": ["A. 质粒", "B. 前病毒(provirus)", "C. 转座子", "D. 端粒"], "a": "B", "e": "逆转录病毒cDNA在整合酶作用下整合入宿主染色体→前病毒，随宿主复制转录。", "kp": "rna_s3_9"}, {"id": "rna_mcq_32", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "转录泡(transcription bubble)是什么？", "o": ["A. 复制泡", "B. 转录时DNA双链局部解开的区域", "C. 启动子", "D. 终止子"], "a": "B", "e": "转录泡=转录时RNA聚合酶处DNA局部解开形成的解链区。", "kp": "rna_s3_6"}, {"id": "rna_mcq_33", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "原核生物rRNA前体加工的主要酶？", "o": ["A. RNaseⅢ/Rnase P/Rnase E", "B. 拼接体", "C. 逆转录酶", "D. PolyA聚合酶"], "a": "A", "e": "原核rRNA加工：甲基化+切割(RNaseⅢ)+修剪(RNase P/E)。", "kp": "rna_s3_0"}, {"id": "rna_mcq_34", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "真核rRNA前体加工由什么RNA指导？", "o": ["A. snRNA", "B. snoRNA(核仁小RNA)", "C. miRNA", "D. tRNA"], "a": "B", "e": "真核rRNA甲基化、假尿苷化、切割由核仁小RNA(snoRNA)指导。", "kp": "rna_s3_1"}, {"id": "rna_mcq_35", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "tRNA前体3'端CCAOH由什么酶添加？", "o": ["A. RNase P", "B. tRNA核苷酰转移酶", "C. PolyA聚合酶", "D. 逆转录酶"], "a": "B", "e": "tRNA核苷酰转移酶在3'端添加CCAOH。真核tRNA的CCA是后加的。", "kp": "rna_s3_0"}, {"id": "rna_mcq_36", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "类型I自我拼接需要什么介导？", "o": ["A. 蛋白质", "B. 鸟苷(鸟苷酸)", "C. 套索", "D. ATP"], "a": "B", "e": "类型I自我拼接由鸟苷(鸟苷酸)的3'-OH介导转酯反应。类型II形成套索。", "kp": "rna_s3_0"}, {"id": "rna_mcq_37", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "新冠病毒的基因组是？", "o": ["A. 双链DNA", "B. 单链正链RNA(+ssRNA,约29900nt)", "C. 单链负链RNA", "D. 双链RNA"], "a": "B", "e": "SARS-CoV-2基因组为1条正链RNA(+ssRNA)29891核苷酸，编码S/E/M/N和Nsp1-16。", "kp": "rna_s3_9"}, {"id": "rna_mcq_38", "mod": "模块四：RNA复制/RNAi/逆转录", "modI": 3, "q": "新冠病毒进入宿主细胞结合的受体是？", "o": ["A. CD4", "B. ACE2(血管紧张素转化酶2)", "C. CCR5", "D. 胰岛素受体"], "a": "B", "e": "SARS-CoV-2的S刺突蛋白与宿主细胞表面ACE2受体结合→膜融合→进入细胞。", "kp": "rna_s3_5"}], "judge": [], "fill": [{"id": "rna_fill_1", "modI": 0, "q": "转录是以________为模板合成RNA的过程,催化该过程的酶是________。", "a": "DNA(模板链),RNA聚合酶(DNA指导的RNA聚合酶)", "kp": "rna_s0_0"}, {"id": "rna_fill_2", "modI": 0, "q": "不对称转录中,与RNA顺序相同的链称________,提供转录模板的链称________。", "a": "编码链(+链),模板链(-链)", "kp": "rna_s0_3"}, {"id": "rna_fill_3", "modI": 0, "q": "原核启动子-10区称________(序列TATAAT),-35区序列是________,提供RNA聚合酶全酶识别信号。", "a": "Pribnow box,TTGACA", "kp": "rna_s0_8"}, {"id": "rna_fill_4", "modI": 0, "q": "原核RNA聚合酶核心酶是________,识别启动子的亚基是________。", "a": "α2ββ',σ因子", "kp": "rna_s0_12"}, {"id": "rna_fill_5", "modI": 0, "q": "RNA聚合酶催化方向是________,________(需要/不需要)引物,________(有/无)校对活性。", "a": "5'→3',不需要,无", "kp": "rna_s0_12"}, {"id": "rna_fill_6", "modI": 1, "q": "真核RNA聚合酶Ⅰ转录________,RNA聚合酶Ⅱ转录________,RNA聚合酶Ⅲ转录________。", "a": "rRNA(5.8S/18S/28S),mRNA/大多数snRNA,tRNA/5SRNA等小RNA", "kp": "rna_s1_4"}, {"id": "rna_fill_7", "modI": 2, "q": "真核mRNA前体(hnRNA)加工包括:5'端________、3'端________、________(去除内含子)和甲基化。", "a": "加帽(m7G),加polyA尾,拼接", "kp": "rna_s2_0"}, {"id": "rna_fill_8", "modI": 2, "q": "真核mRNA内含子5'端为________,3'端为________(GU-AG规则);分支点保守序列是________。", "a": "GU,AG,UACUAAC", "kp": "rna_s2_4"}, {"id": "rna_fill_9", "modI": 2, "q": "RNase P由________和________组成,其________单独具有催化活性,是________(核酶)。", "a": "蛋白质,RNA(M1RNA),RNA,核酶(ribozyme)", "kp": "rna_s2_10"}, {"id": "rna_fill_10", "modI": 3, "q": "逆转录是以________为模板合成DNA,催化酶是________,它兼有________、________和________三种酶活力。", "a": "RNA,逆转录酶,RNA指导的DNA聚合酶,DNA指导的DNA聚合酶,核糖核酸酶H", "kp": "rna_s3_8"}, {"id": "rna_fill_11", "modI": 3, "q": "逆转录病毒典型三个基因是________(核心蛋白)、________(蛋白酶/整合酶/逆转录酶)、________(包膜糖蛋白)。", "a": "gag,pol,env", "kp": "rna_s3_9"}, {"id": "rna_fill_12", "modI": 3, "q": "RNAi中,siRNA/miRNA与________复合物结合,降解靶mRNA;2006年诺贝尔奖授予________和________。", "a": "RISC(RNA诱导沉默复合物),Fire,Mello", "kp": "rna_s3_0"}, {"id": "rna_fill_13", "modI": 1, "q": "转录抑制剂中,利福平抑制________,α-鹅膏蕈碱抑制________,放线菌素D________。", "a": "细菌RNA聚合酶β亚基,真核RNA聚合酶Ⅱ,插入DNA双链碱基对之间", "kp": "rna_s1_7"}], "short": [{"id": "rna_short_1", "modI": 0, "q": "简述原核生物RNA合成的转录过程(模板识别、起始、延伸、终止)。", "a": "【模板识别】\u000bRNA聚合酶在σ因子协助下结合到启动子上，DNA双链局部打开形成转录泡。\u000b\u000b【转录起始】\u000b①RNA聚合酶催化合成最初2~9个核苷酸(第一个通常ATP/GTP，新生链5'端pppA或pppG)\u000b②σ因子脱离核心酶\u000b\u000b【延伸】\u000b核心酶α2ββ'催化RNA链5'→3'延长\u000b\u000b【终止】\u000b①RNA聚合酶感知终止信号，NusA识别终止子→转录终止，RNA链释放\u000b②核心酶自模板脱落，重新与σ因子结合参与下次转录\u000b③依赖ρ的终止：ρ因子(NTP酶+解螺旋酶)解开RNA-DNA杂交体\u000b\u000b【关键】\u000b核心酶(α2ββ')负责延长，σ因子负责起始识别。", "kp": "rna_s0_12"}, {"id": "rna_short_2", "modI": 1, "q": "比较原核生物与真核生物转录的异同。", "a": "【相同点】\u000b①都是DNA指导的RNA合成\u000b②合成方向5'→3'，不需引物\u000b③都以DNA模板链为模板\u000b④都需启动子\u000b\u000b【不同点】\u000b①RNA聚合酶:原核1种(α2ββ'σ) vs 真核3种(PolⅠ/Ⅱ/Ⅲ)\u000b②启动子识别:原核σ因子直接识别 vs 真核需通用转录因子(TFⅡ)装配前起始复合物\u000b③转录单位:原核多顺反子 vs 真核单顺反子\u000b④部位:原核核区 vs 真核核内(转录翻译分开)\u000b⑤mRNA加工:原核mRNA一般不需加工 vs 真核hnRNA需加帽/加尾/拼接\u000b⑥转录与翻译:原核偶联 vs 真核分开\u000b⑦终止:原核有rho依赖/不依赖两类 vs 真核终止机制尚不清楚", "kp": "rna_s1_5"}, {"id": "rna_short_3", "modI": 1, "q": "简述真核生物RNA聚合酶Ⅱ的转录起始过程。", "a": "真核PolⅡ不能直接识别启动子，需通用转录因子装配前起始复合物(PIC)。\u000b\u000b【装配】\u000b①TFⅡD识别结合TATA框(TBP亚基)\u000b②TFⅡA稳定TFⅡD-TATA框结合\u000b③TFⅡB结合TBP，引进TFⅡF-PolⅡ\u000b④TFⅡF与PolⅡ结合，参与解链\u000b⑤TFⅡE引入TFⅡH\u000b⑥TFⅡH具解旋酶和激酶活性\u000b\u000b【起始】\u000b前起始复合物作用下DNA双链分开→开放复合物→PolⅡ开始合成RNA\u000b\u000b【延伸】\u000bPolⅡ被磷酸化(CTD)→构象改变→脱离起始复合物→沿模板滑动延伸\u000b\u000b【终止】\u000b机制尚不清楚；PolⅡ去磷酸化参与下一轮催化\u000b\u000b【关键】\u000b6种通用转录因子:TFⅡD/A/B/F/E/H", "kp": "rna_s1_4"}, {"id": "rna_short_4", "modI": 2, "q": "简述真核生物mRNA前体的加工(加帽、加尾、拼接)。", "a": "真核mRNA前体(hnRNA)需三项主要加工:\u000b\u000b【5'端加帽】\u000b①磷酸酶切去5'端磷酸\u000b②鸟苷酰转移酶加鸟苷酸→5'-5'三磷酸连接\u000b③甲基转移酶(S-腺苷Met)甲基化鸟嘌呤N7→m7G帽子\u000b帽结构:m7G5'ppp5'NmpNp-(Cap0/CapI/CapII)\u000b功能:保护5'端、促进翻译起始、剪接\u000b\u000b【3'端加尾】\u000b加尾信号AAUAAA→内切酶在其3'端11-30nt切断→PolyA聚合酶加20~200个A\u000b组蛋白mRNA无polyA尾\u000b\u000b【拼接】\u000b去除内含子、连接外显子\u000bGU-AG规则、分支点UACUAAC\u000b由拼接体(U1/U2/U4/U5/U6 snRNP+蛋白)催化两次转酯反应\u000b\u000b【意义】\u000b成熟mRNA才能被翻译，加工增加了基因产物多样性(选择性拼接)", "kp": "rna_s2_0"}, {"id": "rna_short_5", "modI": 2, "q": "简述RNA拼接(拼接体拼接)的分子机制。", "a": "真核mRNA前体拼接体拼接机制(两次转酯反应):\u000b\u000b【拼接体装配】\u000b①U1 snRNP结合5'拼接点\u000b②U2 snRNP结合分支点(UACUAAC)\u000b③U4/U6+U5 snRNP三聚体进入\u000b\u000b【第一次转酯反应】\u000b①U1、U4释放\u000b②U6结合5'拼接点，U6与U2结合\u000b③分支点未配对A的2'-OH亲核攻击5'拼接点磷酸二酯键\u000b④5'拼接点断开，形成套索结构，释放5'外显子3'-OH\u000b\u000b【第二次转酯反应】\u000b①U5使5'和3'外显子靠近\u000b②5'外显子3'-OH攻击3'拼接点磷酸二酯键\u000b③3'拼接点断开，外显子连接，内含子以套索形式释放\u000b\u000b【关键】\u000b①GU-AG规则(内含子5'GU、3'AG)\u000b②分支点A的2'-OH是关键\u000b③两次转酯反应无ATP消耗\u000b④snRNP起催化作用", "kp": "rna_s2_4"}, {"id": "rna_short_6", "modI": 3, "q": "简述逆转录酶的性质、逆转录过程及生物学意义。", "a": "【逆转录酶性质】\u000b兼三种酶活力:\u000b①RNA指导的DNA聚合酶(RNA→DNA)\u000b②DNA指导的DNA聚合酶(DNA→DNA)\u000b③核糖核酸酶H(水解RNA-DNA杂交体的RNA)\u000b需dNTP、模板和引物(tRNA)、Mg2+和还原剂，方向5'→3'\u000b\u000b【逆转录过程】\u000b①病毒RNA侵染宿主\u000b②以tRNA为引物，RNA指导DNA聚合酶合成DNA\u000b③形成RNA-cDNA杂交分子\u000b④核糖核酸酶H水解RNA\u000b⑤DNA指导DNA聚合酶合成双链DNA\u000b⑥整合酶使双链DNA整合入宿主染色体→前病毒\u000b⑦前病毒随宿主复制转录\u000b\u000b【生物学意义】\u000b①逆转录酶是研究DNA-RNA关系、DNA克隆的重要工具酶(cDNA合成、反推RNA顺序)\u000b②了解RNA病毒致癌机理\u000b③揭示HIV致病机理提供防治策略\u000b④逆转录病毒可作基因治疗载体", "kp": "rna_s3_11"}, {"id": "rna_short_7", "modI": 3, "q": "简述RNA干扰(RNAi)的机制和生物学意义。", "a": "【RNAi定义】\u000b由双链RNA(dsRNA)引发的特异性基因沉默现象。\u000b\u000b【机制】\u000b①dsRNA(内源miRNA前体或外源长dsRNA)被RNA内切酶(Dicer)切成小片段\u000b②siRNA(~23nt)或miRNA(70-90nt前体加工而来)\u000b③siRNA/miRNA与RISC(RNA诱导沉默复合物)结合\u000b④RISC中Argonaute(Ago)蛋白具内切酶活性\u000b⑤siRNA引导RISC识别互补的靶mRNA→降解靶mRNA\u000b⑥miRNA不完全互补→抑制翻译\u000b\u000b【基因沉默类型】\u000b①转录前水平:DNA修饰/异染色质化\u000b②转录后水平:靶mRNA降解或抑制翻译\u000b\u000b【生物学意义】\u000b①基因表达调控的重要机制\u000b②抵抗病毒侵染、转座子\u000b③研究基因功能的工具(基因敲低)\u000b④疾病治疗(基因治疗)、农业应用\u000b\u000b【里程碑】\u000b2006年诺贝尔奖授予Fire和Mello", "kp": "rna_s3_11"}, {"id": "rna_short_8", "modI": 2, "q": "简述原核生物和真核生物rRNA及tRNA前体的加工。", "a": "【rRNA前体加工】\u000b原核(E.coli):\u000b①7个rRNA转录单位(16S/23S/5S+tRNA基因)\u000b②加工:甲基化(2'-OH,约30个)+切割(RNaseⅢ)+修剪(RNase P/E)\u000b\u000b真核:\u000b①rRNA基因多拷贝(几十~几千)，成簇排列\u000b②16-18S/5.8S/26-28S组成一个转录单位\u000b③甲基化程度更高(>100个)\u000b④甲基化、假尿苷化、切割由snoRNA(核仁小RNA)指导\u000b\u000b【tRNA前体加工】\u000b①核酸内切酶两端切断(RNase P切5'端、RNase F切3'端)\u000b②核酸外切酶(RNase D)3'端修剪\u000b③3'端添加CCAOH(tRNA核苷酰转移酶)\u000b④核苷酸修饰和异构化(假尿苷、甲基化等)\u000b⑤剪接去除内含子(某些真核)\u000b\u000b【关键】\u000bRNase P的RNA(M1RNA)具催化活性→核酶\u000b真核tRNA的3'端CCA是后加的", "kp": "rna_s2_0"}, {"id": "rna_short_9", "modI": 3, "q": "简述RNA的编辑及其生物学意义。", "a": "【RNA编辑定义】\u000b改变RNA的编码序列(转录后修饰编码信息)。\u000b\u000b【编辑类型】\u000b①U的插入与删除(guide RNA指导)——锥虫线粒体mRNA\u000b②C、A或U的插入\u000b③C→U转变\u000b\u000b【实例】\u000b①锥虫线粒体细胞色素氧化酶亚基II mRNA：移码位点附近插入4个额外U(20S复合体:核酸内切酶+末端尿苷酰转移酶+RNA连接酶)\u000b②载脂蛋白apoB-100基因:C→U使CAA(谷氨酰胺)→UAA(终止密码)→小肠产生apoB-48(肝产生apoB-100)\u000b\u000b【生物学意义】\u000b①消除移码突变的危害\u000b②增加基因产物的多样性\u000b③使基因产物获得新的结构和功能\u000b④是基因调控的重要方式\u000b⑤促进生物进化", "kp": "rna_s3_11"}], "calc": [{"id": "rna_calc_1", "modI": 2, "q": "分析真核生物mRNA前体拼接的两次转酯反应,说明为何拼接不需消耗ATP。", "a": "两次转酯反应断裂一个磷酸二酯键同时形成一个新键,能量守恒不需ATP", "steps": "【第一次转酯反应】\u000b分支点A的2'-OH亲核攻击5'拼接点的磷酸二酯键:\u000b• 断裂:5'外显子与内含子之间的磷酸二酯键\u000b• 形成:分支点A与新5'端之间新的2'-5'磷酸二酯键(套索)\u000b• 能量:断裂键释放的能量恰好用于形成新键\u000b\u000b【第二次转酯反应】\u000b5'外显子3'-OH攻击3'拼接点磷酸二酯键:\u000b• 断裂:3'拼接点(内含子与3'外显子之间)磷酸二酯键\u000b• 形成:5'外显子与3'外显子之间磷酸二酯键(外显子连接)\u000b• 释放:内含子以套索形式释放\u000b\u000b【为何不需ATP】\u000b转酯反应=磷酸二酯键的转移(断裂一个+形成一个):\u000b①断裂磷酸二酯键释放的键能与形成新键所需键能相当\u000b②反应前后磷酸二酯键数目不变(2个→2个)\u000b③无需额外的能量输入(与需ATP的DNA连接酶不同)\u000b\u000b【对比】\u000bDNA连接酶需ATP/NAD+(因要把游离的5'-P和3'-OH连接起来需活化)\u000b拼接是转酯反应(键的转移),不需额外活化", "kp": "rna_s2_0"}, {"id": "rna_calc_2", "modI": 0, "q": "论述转录与DNA复制的异同。", "a": "转录与复制都是模板指导的聚合反应,但在模板、酶、产物、保真性等方面有本质区别", "steps": "【相同点】\u000b①都以DNA为模板\u000b②都按碱基互补配对原则\u000b③链延伸方向都是5'→3'\u000b④都需核苷三磷酸为底物\u000b⑤都形成磷酸二酯键\u000b\u000b【不同点】\u000b①模板:复制DNA两条链都作模板;转录仅模板链作模板(不对称)\u000b②酶:复制DNA聚合酶(需引物有校对);转录RNA聚合酶(不需引物无校对)\u000b③底物:复制dNTP;转录NTP\u000b④产物:复制DNA;转录RNA(mRNA/rRNA/tRNA)\u000b⑤保真性:复制高(10^-9~10^-10);转录较低(10^-4)\u000b⑥范围:复制全基因组;转录选择性\u000b⑦引物:复制需RNA引物;转录不需引物\u000b\u000b【总结】\u000b复制保真性高、全基因组、有校对(遗传信息稳定传递)\u000b转录选择性、无校对、可反复进行(基因表达调控)", "kp": "rna_s0_2"}, {"id": "rna_calc_3", "modI": 3, "q": "论述RNA生物功能的多样性(RNA世界假说的证据)。", "a": "RNA既能存储遗传信息又能催化反应,是生命起源RNA世界假说的核心", "steps": "【RNA的多种功能】\u000b①遗传信息载体和翻译中介:mRNA携带密码、rRNA组成核糖体、tRNA转运氨基酸\u000b②催化功能(核酶):RNase P的M1RNA具催化活性、四膜虫rRNA自我拼接、核糖体肽键形成由23S rRNA催化\u000b③转录后加工:snoRNA参与rRNA加工、snRNA参与hnRNA拼接、端粒酶RNA作模板\u000b④基因表达调控:miRNA/siRNA参与RNAi、反义RNA、核开关\u000b⑤其他:引导RNA参与RNA编辑\u000b\u000b【RNA世界假说的证据】\u000b①RNA兼具信息存储(DNA功能)和催化(蛋白质功能)\u000b②rRNA催化肽键形成→核糖体本质是核酶\u000b③RNA可以自我复制(RNA复制酶)\u000b④RNA可逆转录为DNA\u000b\u000b【结论】\u000bRNA的多功能性支持生命起源早期可能是RNA世界\u000b→RNA先出现,既能催化又能存储信息\u000b→后来DNA(更稳定)接管信息存储,蛋白质(更多样)接管催化\u000b→RNA保留中间角色(遗传信息流动的桥梁)", "kp": "rna_s3_0"}, {"id": "rna_calc_4", "modI": 3, "q": "论述逆转录病毒的致病机理及逆转录在分子生物学中的应用。", "a": "逆转录病毒通过前病毒形式整合宿主基因组致病,逆转录酶是分子克隆核心工具酶", "steps": "【逆转录病毒致病机理】\u000b①病毒颗粒(表面蛋白+跨膜蛋白)与宿主细胞融合\u000b②RNA在细胞质逆转录为cDNA\u000b③整合酶使cDNA整合入宿主染色体→前病毒\u000b④前病毒随宿主DNA复制转录→产生新病毒或癌变\u000b\u000b【致癌机理】\u000b①前病毒插入宿主基因组→插入突变激活原癌基因\u000b②病毒携带癌基因(如人类嗜T细胞病毒癌基因编码酪氨酸蛋白激酶,高表达致细胞分裂失控)\u000b③前病毒启动子驱动邻近基因过度表达\u000b\u000b【HIV致病机理】\u000b①HIV是逆转录病毒,感染CD4+T细胞\u000b②逆转录酶易错(无校对)→高突变率→逃避免疫和耐药\u000b③整合入基因组潜伏→慢性感染\u000b④破坏免疫系统→艾滋病\u000b\u000b【逆转录的应用】\u000b①cDNA合成:逆转录酶以mRNA为模板合成cDNA→构建cDNA文库\u000b②RT-PCR:检测基因表达、诊断病毒\u000b③反推RNA顺序\u000b④基因治疗:逆转录病毒作载体导入治疗基因\u000b\u000b【关键】\u000b逆转录酶无校对→高突变率→既是病毒进化和耐药的原因,也是分子克隆中引入错误的问题", "kp": "rna_s3_11"}, {"id": "rna_calc_5", "modI": 3, "q": "分析新冠病毒(SARS-CoV-2)的结构、基因组和感染复制过程。", "a": "SARS-CoV-2是正链RNA病毒,S蛋白结合ACE2受体入侵,RNA复制+翻译组装出芽", "steps": "【病毒结构】\u000b①刺突蛋白S(结合受体)\u000b②包膜蛋白E\u000b③膜蛋白M\u000b④核衣壳蛋白N\u000b\u000b【基因组】\u000b①1条正链RNA(+ssRNA),29891核苷酸\u000b②编码9860氨基酸\u000b③结构蛋白4个(S/E/M/N)\u000b④非结构蛋白16个(Nsp1-16)\u000b\u000b【关键非结构蛋白】\u000bNsp1:参与RNA加工\u000bNsp3/Nsp5:蛋白酶(多肽链加工)\u000bNsp12:RNA依赖RNA聚合酶(RdRp)\u000bNsp13:解旋酶\u000b\u000b【感染复制过程】\u000b①吸附:S蛋白与宿主细胞ACE2受体结合\u000b②侵入:跨膜丝氨酸蛋白酶2(TMPRSS2)激活,膜融合\u000b③释放:遗传物质RNA释放入胞质\u000b④翻译:以基因组RNA为模板翻译多聚蛋白pp1a/b\u000b⑤蛋白水解:水解成16个非结构蛋白\u000b⑥转录复制:形成RNA聚合酶复合物,转录复制基因组\u000b⑦翻译结构蛋白:S/M/E在内质网翻译,N在核糖体翻译\u000b⑧组装:S/M/E/N组装病毒颗粒\u000b⑨出芽释放\u000b\u000b【抗病毒靶点】\u000bRdRp(瑞德西韦靶点)、蛋白酶(帕罗维德靶点)、S蛋白(疫苗靶点)", "kp": "rna_s3_5"}], "term": [{"id": "rna_term_1", "modI": 0, "term": "转录(Transcription)", "def": "①以DNA为模板、按碱基互补原则合成RNA的过程，即DNA指导下RNA的合成（定义）。②由RNA聚合酶(DNA指导的RNA聚合酶)催化（酶）。③需NTP为底物，方向5'→3'，不需引物（特点）。④是遗传信息从DNA流向RNA的过程，是基因表达的第一步（意义）。", "kps": "①定义(2分)②酶(1分)③特点(1分)④意义(1分)", "kp": "rna_s0_6"}, {"id": "rna_term_2", "modI": 0, "term": "不对称转录", "def": "①转录时DNA双链不是同时作模板，只有一条链作模板的转录方式（定义）。②编码链(+链)：与RNA顺序相同的链(仅T代U)（编码链）。③模板链(-链)：为RNA提供模板的链（模板链）。④不同基因的模板链可位于DNA不同链上，基因转录有选择性（特点）。", "kps": "①定义(2分)②编码链(1分)③模板链(1分)④选择性(1分)", "kp": "rna_s0_3"}, {"id": "rna_term_3", "modI": 0, "term": "编码链/模板链", "def": "①编码链(coding strand,+链)：与转录出的RNA顺序相同的一条链(仅T代替U)（编码链）。②模板链(template strand,-链)：为RNA提供转录模板的链（模板链）。③RNA按碱基互补原则以模板链为模板合成，故RNA序列与编码链一致、与模板链互补（关系）。", "kps": "①编码链定义(2分)②模板链定义(2分)③互补关系(1分)", "kp": "rna_s0_3"}, {"id": "rna_term_4", "modI": 0, "term": "转录单位", "def": "①RNA转录起始于DNA模板特定位点、在另一位点终止，此转录区域称转录单位（定义）。②原核：多顺反子(一个转录单位含多个基因→多种蛋白质)（原核）。③真核：单顺反子(一个转录单位含1个基因→1种蛋白质)（真核）。", "kps": "①定义(2分)②原核多顺反子(1分)③真核单顺反子(2分)", "kp": "rna_s0_5"}, {"id": "rna_term_5", "modI": 0, "term": "启动子(Promoter)", "def": "①RNA聚合酶识别、结合和开始转录的一段DNA序列，具特定核苷酸顺序（定义）。②原核启动子含-10区(Pribnow box,TATAAT)和-35区(TTGACA)（原核）。③真核启动子分Ⅰ/Ⅱ/Ⅲ三类，Ⅱ类含TATA框、起始子等（真核）。④启动子决定转录起始的位置和效率（功能）。", "kps": "①定义(2分)②原核结构(1分)③真核结构(1分)④功能(1分)", "kp": "rna_s0_6"}, {"id": "rna_term_6", "modI": 0, "term": "Pribnow盒(Pribnow Box)", "def": "①原核生物启动子-10区的一段6bp保守序列(TATAAT)（定义）。②是RNA聚合酶结合后DNA双链局部解开的区域（功能）。③与-35区TTGACA(提供RNA聚合酶全酶识别信号)共同构成原核启动子识别区（结构）。", "kps": "①定义(2分)②-10区位置(1分)③功能(1分)④与-35区关系(1分)", "kp": "rna_s0_8"}, {"id": "rna_term_7", "modI": 0, "term": "终止子(Terminator)", "def": "①提供转录终止信号的DNA序列（定义）。②原核终止子在终止点前有回文结构→RNA形成发夹结构→聚合酶减慢/停止转录（机制）。③两类：不依赖rho的终止子(简单终止子)和依赖rho的终止子（分类）。", "kps": "①定义(2分)②发夹结构机制(2分)③两类(1分)", "kp": "rna_s0_11"}, {"id": "rna_term_8", "modI": 0, "term": "ρ因子(Rho Factor)", "def": "①参与原核生物依赖rho的转录终止的终止因子（定义）。②具NTP酶活力和RNA-DNA解螺旋酶活力（活性）。③沿RNA链3'→5'移动，在终止位点解开RNA-DNA杂交体→释放RNA（机制）。", "kps": "①定义(2分)②两种活力(1分)③终止机制(2分)", "kp": "rna_s0_6"}, {"id": "rna_term_9", "modI": 0, "term": "RNA聚合酶全酶/核心酶", "def": "①原核RNA聚合酶全酶由α2ββ'σ五个亚基组成(含Zn2+)（全酶）。②核心酶α2ββ'：催化RNA链延长（核心酶）。③σ因子(起始亚基)：识别启动子，促进转录起始（σ因子）。④起始后σ脱离，核心酶延伸（过程）。", "kps": "①全酶组成(2分)②核心酶功能(1分)③σ因子功能(1分)④起始后σ脱离(1分)", "kp": "rna_s0_12"}, {"id": "rna_term_10", "modI": 1, "term": "转录泡(Transcription Bubble)", "def": "①转录过程中，RNA聚合酶处DNA双链局部解开的区域（定义）。②是RNA合成的活性位点，RNA聚合酶在转录泡内催化RNA合成（功能）。③随转录沿模板移动（特点）。", "kps": "①定义(2分)②功能(2分)③移动(1分)", "kp": "rna_s1_0"}, {"id": "rna_term_11", "modI": 2, "term": "前起始复合物(PIC)", "def": "①真核生物转录起始时，RNA聚合酶与通用转录因子在启动子处装配成的复合物（定义）。②真核RNA聚合酶不能识别启动子，必须与通用转录因子装配成PIC才能起始（必要性）。③以Ⅱ类启动子为例，至少涉及6种通用转录因子(TFⅡD/A/B/F/E/H)（组成）。", "kps": "①定义(2分)②必要性(1分)③6种通用因子(2分)", "kp": "rna_s2_2"}, {"id": "rna_term_12", "modI": 0, "term": "转录后加工(Post-transcriptional Processing)", "def": "①RNA前体转变为成熟RNA的过程（定义）。②包括：切割、修剪、添加、修饰和异构化、拼接、编辑、再编码（类型）。③真核mRNA前体加工：5'加帽、3'加尾、拼接（真核mRNA）。④rRNA/tRNA前体也需加工(甲基化、切割、修饰等)（其他）。", "kps": "①定义(2分)②加工类型(1分)③真核mRNA加工(1分)④rRNA/tRNA(1分)", "kp": "rna_s0_6"}, {"id": "rna_term_13", "modI": 2, "term": "hnRNA(核内不均一RNA)", "def": "①真核生物mRNA的前体，因分子大小不均一而得名（定义）。②在核内合成，是RNA聚合酶Ⅱ的转录产物（来源）。③需经加帽、加尾、拼接等加工才成为成熟mRNA（加工）。", "kps": "①定义(2分)②来源(1分)③加工(2分)", "kp": "rna_s2_0"}, {"id": "rna_term_14", "modI": 2, "term": "5'帽结构(5' Cap)", "def": "①真核mRNA 5'端的特殊结构m7G5'ppp5'NmpNp-（定义）。②由磷酸酶、鸟苷酰转移酶、甲基转移酶催化(需S-腺苷Met)（合成）。③分Cap0/CapI/CapII三型（类型）。④功能：保护mRNA 5'端免遭降解、促进翻译起始、参与剪接（功能）。", "kps": "①定义(2分)②合成酶(1分)③类型(1分)④功能(1分)", "kp": "rna_s2_9"}, {"id": "rna_term_15", "modI": 2, "term": "polyA尾(Poly(A) Tail)", "def": "①真核mRNA 3'端的多聚腺苷酸尾巴(20~200个A)（定义）。②在加尾信号AAUAAA的3'端11~30nt处切断，由PolyA聚合酶添加（合成）。③功能：保护mRNA 3'端、促进mRNA出核和翻译（功能）。④组蛋白mRNA等无polyA尾（例外）。", "kps": "①定义(2分)②加尾信号(1分)③功能(1分)④组蛋白例外(1分)", "kp": "rna_s2_2"}, {"id": "rna_term_16", "modI": 2, "term": "RNA拼接(Splicing)", "def": "①真核生物断裂基因转录物加工中，去除内含子、使外显子成为连续序列的过程（定义）。②四种方式：类型I自我拼接、类型II自我拼接、真核mRNA拼接体拼接、核tRNA酶促拼接（方式）。③真核mRNA拼接遵循GU-AG规则，由拼接体催化两次转酯反应（机制）。", "kps": "①定义(2分)②四种方式(1分)③GU-AG规则(1分)④转酯反应(1分)", "kp": "rna_s2_3"}, {"id": "rna_term_17", "modI": 2, "term": "GU-AG规则", "def": "①真核生物mRNA前体的内含子5'端为GU、3'端为AG的拼接规则（定义）。②是真核mRNA内含子两端的高度保守序列（特点）。③作为拼接体识别拼接位点的信号（功能）。", "kps": "①定义(2分)②保守性(2分)③识别信号(1分)", "kp": "rna_s2_4"}, {"id": "rna_term_18", "modI": 2, "term": "拼接体(Spliceosome)", "def": "①真核mRNA前体拼接时，由U1/U2/U4/U5/U6 snRNP和约50种蛋白质组成的复合物（定义）。②snRNP由snRNA(富含U)+蛋白质组成（组成）。③催化两次转酯反应完成内含子切除和外显子连接（功能）。", "kps": "①定义(2分)②snRNP组成(1分)③两次转酯反应(2分)", "kp": "rna_s2_5"}, {"id": "rna_term_19", "modI": 2, "term": "选择性拼接(Alternative Splicing)", "def": "①一个基因的转录产物在不同细胞/发育阶段/生理状态下，通过不同拼接方式得到不同mRNA和翻译产物的现象（定义）。②例：鼠降钙素mRNA前体两个polyA位点，甲状腺产降钙素、脑产降钙素基因相关肽（实例）。③意义：增加基因产物多样性、基因表达调节、进化（意义）。", "kps": "①定义(2分)②实例(1分)③意义(2分)", "kp": "rna_s2_7"}, {"id": "rna_term_20", "modI": 2, "term": "核酶(Ribozyme)", "def": "①具有催化功能的RNA分子（定义）。②例：RNase P的RNA(M1RNA)单独具切割活性；四膜虫rRNA前体自我拼接(L19RNA)（实例）。③发现意义：推翻酶都是蛋白质的传统观念，支持RNA世界假说（意义）。", "kps": "①定义(2分)②实例(2分)③意义(1分)", "kp": "rna_s2_10"}, {"id": "rna_term_21", "modI": 2, "term": "RNase P", "def": "①催化tRNA前体5'端成熟的核酸内切酶（定义）。②由蛋白质和RNA(M1RNA)组成（组成）。③原核RNase P的RNA(375nt)单独具切割活性→核酶（催化本质）。", "kps": "①定义(2分)②蛋白+RNA组成(1分)③RNA具催化活性(2分)", "kp": "rna_s2_0"}, {"id": "rna_term_22", "modI": 3, "term": "RNA编辑(RNA Editing)", "def": "①改变RNA编码序列的转录后修饰过程（定义）。②类型：U的插入与删除(guide RNA指导)、C/A/U插入、C→U等（类型）。③例：锥虫线粒体mRNA插入U、apoB mRNA C→U产生终止密码（实例）。④意义：消除移码突变危害、增加基因产物多样性、基因调控（意义）。", "kps": "①定义(2分)②类型(1分)③实例(1分)④意义(1分)", "kp": "rna_s3_0"}, {"id": "rna_term_23", "modI": 3, "term": "RNAi(RNA干扰)", "def": "①由双链RNA引发的特异性基因沉默现象（定义）。②机制：dsRNA被RNA内切酶(Dicer)切成siRNA(~23nt)/miRNA→与RISC结合→降解靶mRNA或抑制翻译（机制）。③基因沉默含转录前水平(DNA修饰/异染色质化)和转录后水平(mRNA降解/翻译抑制)（类型）。④2006年诺贝尔奖(Fire和Mello)（里程碑）。", "kps": "①定义(2分)②机制(2分)③类型(1分)④诺贝尔奖(1分)", "kp": "rna_s3_0"}, {"id": "rna_term_24", "modI": 0, "term": "RNA复制酶(RNA Replicase)", "def": "①以RNA为模板、催化RNA合成的酶(RNA指导下RNA合成)（定义）。②以4种NTP为底物，聚合方向5'→3'（特点）。③例：噬菌体Qβ复制酶(β亚基催化,α/γ/δ来自宿主)（实例）。④是RNA病毒复制的关键酶（意义）。", "kps": "①定义(2分)②特点(1分)③Qβ实例(1分)④意义(1分)", "kp": "rna_s0_0"}, {"id": "rna_term_25", "modI": 0, "term": "逆转录(Reverse Transcription)", "def": "①以RNA为模板、按RNA中核苷酸顺序合成DNA的过程(RNA指导的DNA合成)（定义）。②由逆转录酶催化（酶）。③逆转录酶兼有RNA指导DNA聚合酶、DNA指导DNA聚合酶、核糖核酸酶H三种活力（酶活力）。④是逆转录病毒复制的关键步骤（意义）。", "kps": "①定义(2分)②酶(1分)③三种活力(1分)④意义(1分)", "kp": "rna_s0_6"}, {"id": "rna_term_26", "modI": 1, "term": "逆转录酶(Reverse Transcriptase)", "def": "①催化RNA→DNA合成的酶（定义）。②1970年Temin和Baltimore从致癌RNA病毒中发现，1975年诺贝尔奖（发现）。③兼三种活力：RNA指导DNA聚合酶、DNA指导DNA聚合酶、核糖核酸酶H（活力）。④需dNTP、模板和tRNA引物、Mg2+，方向5'→3'（条件）。⑤分子克隆核心工具酶(cDNA合成)（应用）。", "kps": "①定义(2分)②发现/诺贝尔(1分)③三种活力(1分)④应用(1分)", "kp": "rna_s1_8"}, {"id": "rna_term_27", "modI": 2, "term": "前病毒(Provirus)", "def": "①逆转录病毒cDNA在整合酶作用下整合入宿主染色体后的DNA形式（定义）。②随宿主细胞DNA复制和转录（特点）。③是逆转录病毒潜伏感染和致癌的分子基础（意义）。④Temin前病毒学说(1964)提出（来源）。", "kps": "①定义(2分)②随宿主复制(1分)③意义(1分)④前病毒学说(1分)", "kp": null}], "preview": null, "appcards": []};